/* =========================================================
   TOURAYS FITNESS V9 — WALK & RUN MODULE
   ========================================================= */
(function(){
  const screen = document.getElementById('walkRunScreen');
  if(!screen) return;

  const $ = id => document.getElementById(id);
  const refs = {
    back: $('wrBackBtn'), start: $('wrStartBtn'), pause: $('wrPauseBtn'), finish: $('wrFinishBtn'),
    clear: $('wrClearHistory'), timer: $('wrTimer'), distance: $('wrDistance'),
    currentPace: $('wrCurrentPace'), averagePace: $('wrAveragePace'), speed: $('wrSpeed'),
    calories: $('wrCalories'), accuracy: $('wrAccuracy'), gps: $('wrGpsState'),
    status: $('wrStatusLabel'), history: $('wrHistoryList'), route: $('wrRouteLine'),
    dot: $('wrLocationDot')
  };

  const state = {
    mode: 'walk', running: false, paused: false, startedAt: 0, elapsedBeforePause: 0,
    timerId: null, watchId: null, distanceKm: 0, lastPoint: null, route: [],
    currentSpeed: 0, accuracy: null
  };

  function formatTime(ms){
    const total = Math.max(0, Math.floor(ms/1000));
    const h = String(Math.floor(total/3600)).padStart(2,'0');
    const m = String(Math.floor((total%3600)/60)).padStart(2,'0');
    const s = String(total%60).padStart(2,'0');
    return `${h}:${m}:${s}`;
  }

  function formatPace(minPerKm){
    if(!isFinite(minPerKm) || minPerKm <= 0) return '--:--';
    const mins = Math.floor(minPerKm);
    const secs = Math.round((minPerKm-mins)*60);
    return `${String(mins).padStart(2,'0')}:${String(secs).padStart(2,'0')}`;
  }

  function elapsedMs(){
    if(!state.running) return state.elapsedBeforePause;
    if(state.paused) return state.elapsedBeforePause;
    return state.elapsedBeforePause + (Date.now() - state.startedAt);
  }

  function haversine(a,b){
    const R = 6371;
    const dLat = (b.lat-a.lat)*Math.PI/180;
    const dLon = (b.lon-a.lon)*Math.PI/180;
    const la1 = a.lat*Math.PI/180, la2 = b.lat*Math.PI/180;
    const h = Math.sin(dLat/2)**2 + Math.cos(la1)*Math.cos(la2)*Math.sin(dLon/2)**2;
    return 2*R*Math.asin(Math.sqrt(h));
  }

  function updateMetrics(){
    const elapsed = elapsedMs();
    refs.timer.textContent = formatTime(elapsed);
    refs.distance.textContent = state.distanceKm.toFixed(2);
    refs.speed.textContent = state.currentSpeed.toFixed(1);
    const hours = elapsed/3600000;
    const avgSpeed = hours > 0 ? state.distanceKm/hours : 0;
    refs.currentPace.textContent = formatPace(state.currentSpeed > 0 ? 60/state.currentSpeed : Infinity);
    refs.averagePace.textContent = formatPace(avgSpeed > 0 ? 60/avgSpeed : Infinity);
    const met = state.mode === 'run' ? 9.8 : 4.3;
    const assumedWeight = 75;
    refs.calories.textContent = Math.round(met * assumedWeight * hours);
    refs.accuracy.textContent = state.accuracy ? Math.round(state.accuracy) : '--';
  }

  function updateRoute(){
    if(state.route.length < 2) return;
    const lats = state.route.map(p=>p.lat), lons = state.route.map(p=>p.lon);
    const minLat=Math.min(...lats), maxLat=Math.max(...lats), minLon=Math.min(...lons), maxLon=Math.max(...lons);
    const latRange=maxLat-minLat || .0001, lonRange=maxLon-minLon || .0001;
    const points = state.route.map(p=>{
      const x = 8 + ((p.lon-minLon)/lonRange)*84;
      const y = 92 - ((p.lat-minLat)/latRange)*84;
      return `${x.toFixed(1)},${y.toFixed(1)}`;
    }).join(' ');
    refs.route.setAttribute('points', points);
    const last = points.split(' ').pop().split(',');
    refs.dot.style.left = `${last[0]}%`;
    refs.dot.style.top = `${last[1]}%`;
  }

  function onPosition(pos){
    const c = pos.coords;
    const point = {lat:c.latitude, lon:c.longitude, time:Date.now()};
    state.accuracy = c.accuracy || null;
    if(!state.paused){
      if(state.lastPoint){
        const segment = haversine(state.lastPoint, point);
        if(segment < 0.25 && (c.accuracy || 999) < 80) state.distanceKm += segment;
      }
      state.lastPoint = point;
      state.route.push(point);
      if(Number.isFinite(c.speed) && c.speed >= 0){
        state.currentSpeed = c.speed * 3.6;
      }else if(state.route.length > 1){
        const prev = state.route[state.route.length-2];
        const dt = (point.time-prev.time)/3600000;
        state.currentSpeed = dt > 0 ? haversine(prev,point)/dt : 0;
      }
      updateRoute();
    }
    refs.gps.textContent = `GPS ±${Math.round(c.accuracy || 0)} m`;
    updateMetrics();
  }

  function onGpsError(){
    refs.gps.textContent = 'GPS unavailable';
  }

  function startGps(){
    if(!navigator.geolocation){
      refs.gps.textContent='GPS unsupported';
      return;
    }
    state.watchId = navigator.geolocation.watchPosition(onPosition,onGpsError,{
      enableHighAccuracy:true, maximumAge:1000, timeout:12000
    });
  }

  function stopGps(){
    if(state.watchId !== null && navigator.geolocation){
      navigator.geolocation.clearWatch(state.watchId);
      state.watchId=null;
    }
  }

  function resetSession(){
    state.running=false; state.paused=false; state.startedAt=0; state.elapsedBeforePause=0;
    state.distanceKm=0; state.lastPoint=null; state.route=[]; state.currentSpeed=0; state.accuracy=null;
    refs.route.setAttribute('points','10,82 20,72 34,75 44,60 58,63 68,45 83,36 91,20');
    refs.dot.style.left='91%'; refs.dot.style.top='20%';
    refs.status.textContent='READY';
    refs.start.textContent=`Start ${state.mode}`;
    refs.pause.textContent='Pause';
    refs.pause.disabled=true; refs.finish.disabled=true;
    updateMetrics();
  }

  function start(){
    if(state.running && state.paused){
      state.paused=false;
      state.startedAt=Date.now();
      refs.pause.textContent='Pause';
      refs.status.textContent='ACTIVE';
      startGps();
      return;
    }
    resetSession();
    state.running=true;
    state.startedAt=Date.now();
    refs.status.textContent='ACTIVE';
    refs.start.textContent='Tracking';
    refs.start.disabled=true;
    refs.pause.disabled=false;
    refs.finish.disabled=false;
    startGps();
    state.timerId=setInterval(updateMetrics,1000);
  }

  function pause(){
    if(!state.running) return;
    if(!state.paused){
      state.elapsedBeforePause=elapsedMs();
      state.paused=true;
      refs.pause.textContent='Resume';
      refs.status.textContent='PAUSED';
      state.currentSpeed=0;
      stopGps();
    }else{
      state.paused=false;
      state.startedAt=Date.now();
      refs.pause.textContent='Pause';
      refs.status.textContent='ACTIVE';
      startGps();
    }
    updateMetrics();
  }

  function saveActivity(){
    const elapsed = elapsedMs();
    if(elapsed < 1000) return;
    const activities = JSON.parse(localStorage.getItem('touraysWalkRunHistory') || '[]');
    const hours=elapsed/3600000;
    const avgSpeed=hours>0?state.distanceKm/hours:0;
    const item={
      id:Date.now(), mode:state.mode, date:new Date().toISOString(),
      duration:elapsed, distance:state.distanceKm,
      pace:avgSpeed>0?60/avgSpeed:null,
      calories:Number(refs.calories.textContent)||0
    };
    activities.unshift(item);
    localStorage.setItem('touraysWalkRunHistory',JSON.stringify(activities.slice(0,30)));
  }

  function finish(){
    if(!state.running) return;
    if(!state.paused) state.elapsedBeforePause=elapsedMs();
    stopGps();
    clearInterval(state.timerId);
    saveActivity();
    state.running=false;
    state.paused=false;
    refs.start.disabled=false;
    refs.pause.disabled=true;
    refs.finish.disabled=true;
    refs.start.textContent=`Start ${state.mode}`;
    refs.status.textContent='SAVED';
    renderHistory();
  }

  function renderHistory(){
    const activities = JSON.parse(localStorage.getItem('touraysWalkRunHistory') || '[]');
    if(!activities.length){
      refs.history.innerHTML='<div class="wr-empty">No completed activities yet.</div>';
      return;
    }
    refs.history.innerHTML = activities.map(a=>{
      const d = new Date(a.date);
      return `<article class="wr-history-item">
        <div class="wr-history-icon">${a.mode==='run'?'🏃':'🚶'}</div>
        <div class="wr-history-copy">
          <strong>${a.mode==='run'?'Outdoor Run':'Outdoor Walk'}</strong>
          <span>${d.toLocaleDateString()} · ${d.toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'})}</span>
        </div>
        <div class="wr-history-stats">
          <strong>${Number(a.distance).toFixed(2)} km</strong>
          <span>${formatTime(a.duration)} · ${a.pace?formatPace(a.pace):'--:--'}/km</span>
        </div>
      </article>`;
    }).join('');
  }

  document.querySelectorAll('.wr-mode').forEach(btn=>{
    btn.addEventListener('click',()=>{
      if(state.running) return;
      document.querySelectorAll('.wr-mode').forEach(x=>x.classList.remove('active'));
      btn.classList.add('active');
      state.mode=btn.dataset.mode;
      refs.start.textContent=`Start ${state.mode}`;
    });
  });

  refs.start.addEventListener('click',start);
  refs.pause.addEventListener('click',pause);
  refs.finish.addEventListener('click',finish);
  refs.clear.addEventListener('click',()=>{
    localStorage.removeItem('touraysWalkRunHistory');
    renderHistory();
  });
  refs.back.addEventListener('click',()=>show('home'));

  function openWalkRun(){
    document.querySelectorAll('.screen').forEach(s=>s.hidden=true);
    screen.hidden=false;
    window.scrollTo({top:0,behavior:'smooth'});
    renderHistory();
  }

  const direct = document.getElementById('openWalkRunBtn');
  if(direct) direct.addEventListener('click',openWalkRun);

  document.addEventListener('click',e=>{
    const el=e.target.closest('button,a,[data-screen],[data-page]');
    if(!el) return;
    const text=(el.textContent||'').trim().toLowerCase();
    const target=((el.dataset&&(`${el.dataset.screen||''} ${el.dataset.page||''}`))||'').toLowerCase();
    if(text.includes('walk') || text.includes('run') || target.includes('walk') || target.includes('run')){
      if(!el.closest('#walkRunScreen')){
        e.preventDefault();
        openWalkRun();
      }
    }
  });

  resetSession();
  renderHistory();
})();


/* =========================================================
   TOURAYS FITNESS V10 — STAGE 2: STABLE BANNER SUPPRESSION
   The unreliable iOS online/install banners are disabled until the
   later dedicated PWA stage. No fitness feature or navigation logic
   is changed here.
   ========================================================= */
(function(){
  const networkStatus = document.getElementById('networkStatus');
  const installBanner = document.getElementById('installAppBanner');

  function suppressLegacyBanners(){
    if(networkStatus){
      networkStatus.hidden = true;
      networkStatus.style.setProperty('display','none','important');
      networkStatus.setAttribute('aria-hidden','true');
    }
    if(installBanner){
      installBanner.hidden = true;
      installBanner.style.setProperty('display','none','important');
      installBanner.setAttribute('aria-hidden','true');
    }
    document.documentElement.classList.remove('is-offline');
  }

  suppressLegacyBanners();
  document.addEventListener('DOMContentLoaded', suppressLegacyBanners, {once:true});
  window.addEventListener('pageshow', suppressLegacyBanners);
  window.addEventListener('online', suppressLegacyBanners);
  window.addEventListener('offline', suppressLegacyBanners);

  // Persist the most important profile and settings inputs automatically.
  const autosaveIds=[
    'weight','height','weeklyGoal','profileName','profileAge','profileTrainingLevel',
    'profileHeight','profileWeight','profileGoal','profileWeeklyGoal',
    'gpsToggle','profileVoiceToggle','profileVibrationToggle','profileCountdownToggle'
  ];

  function restoreAutosave(){
    const saved=JSON.parse(localStorage.getItem('touraysAutosaveSettings')||'{}');
    autosaveIds.forEach(id=>{
      const el=document.getElementById(id);
      if(!el || !(id in saved)) return;
      if(el.type==='checkbox') el.checked=Boolean(saved[id]);
      else el.value=saved[id];
    });
  }

  function saveAutosave(){
    const data={};
    autosaveIds.forEach(id=>{
      const el=document.getElementById(id);
      if(!el) return;
      data[id]=el.type==='checkbox'?el.checked:el.value;
    });
    localStorage.setItem('touraysAutosaveSettings',JSON.stringify(data));
    localStorage.setItem('touraysLastSavedAt',new Date().toISOString());
  }

  restoreAutosave();
  autosaveIds.forEach(id=>{
    const el=document.getElementById(id);
    if(el){
      el.addEventListener('change',saveAutosave);
      el.addEventListener('input',saveAutosave);
    }
  });

  // Flush data before the browser closes or backgrounds the app.
  document.addEventListener('visibilitychange',()=>{
    if(document.visibilityState==='hidden') saveAutosave();
  });
  window.addEventListener('pagehide',saveAutosave);
})();


/* =========================================================
   TOURAYS FITNESS V9 — WORKOUT PLANNER
   ========================================================= */
(function(){
  const screen = document.getElementById('plannerScreen');
  if(!screen) return;

  const dayNames = ['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'];
  const shortDays = ['MON','TUE','WED','THU','FRI','SAT','SUN'];
  const typeIcons = {
    Strength:'🏋️', Cardio:'❤️', Mobility:'🧘', HIIT:'⚡',
    Recovery:'🌿', Outdoor:'🏃'
  };

  const $ = id => document.getElementById(id);
  const refs = {
    back:$('plannerBackBtn'),
    prev:$('plannerPrevWeek'),
    next:$('plannerNextWeek'),
    weekLabel:$('plannerWeekLabel'),
    weekRange:$('plannerWeekRange'),
    weekGrid:$('plannerWeekGrid'),
    auto:$('plannerAutoPlan'),
    create:$('plannerNewWorkout'),
    reset:$('plannerResetWeek'),
    templates:$('plannerTemplateList'),
    modal:$('plannerModal'),
    form:$('plannerWorkoutForm'),
    title:$('plannerModalTitle'),
    editId:$('plannerEditId'),
    name:$('plannerWorkoutName'),
    day:$('plannerWorkoutDay'),
    type:$('plannerWorkoutType'),
    duration:$('plannerWorkoutDuration'),
    intensity:$('plannerWorkoutIntensity'),
    notes:$('plannerWorkoutNotes'),
    deleteBtn:$('plannerDeleteWorkout')
  };

  const storageKey = 'touraysWorkoutPlannerV1';
  const templateKey = 'touraysWorkoutTemplatesV1';
  let weekOffset = 0;
  let draggedId = null;

  function mondayOf(date){
    const d = new Date(date);
    const day = d.getDay();
    const diff = d.getDate() - day + (day === 0 ? -6 : 1);
    d.setDate(diff);
    d.setHours(0,0,0,0);
    return d;
  }

  function addDays(date,days){
    const d = new Date(date);
    d.setDate(d.getDate()+days);
    return d;
  }

  function weekStart(){
    return addDays(mondayOf(new Date()),weekOffset*7);
  }

  function weekKey(){
    return weekStart().toISOString().slice(0,10);
  }

  function defaultWeek(){
    return [
      {id:cryptoId(),day:0,name:'Upper Body Strength',type:'Strength',duration:35,intensity:'Moderate',notes:'Push, pull and core.'},
      {id:cryptoId(),day:1,name:'Outdoor Walk',type:'Outdoor',duration:30,intensity:'Low',notes:'Comfortable recovery pace.'},
      {id:cryptoId(),day:2,name:'Lower Body Strength',type:'Strength',duration:40,intensity:'Moderate',notes:'Squats, lunges and glutes.'},
      {id:cryptoId(),day:3,name:'Mobility Flow',type:'Mobility',duration:20,intensity:'Low',notes:'Hips, shoulders and back.'},
      {id:cryptoId(),day:4,name:'Full Body HIIT',type:'HIIT',duration:25,intensity:'High',notes:'Short intervals with full-body movements.'},
      {id:cryptoId(),day:5,name:'Easy Run',type:'Outdoor',duration:30,intensity:'Moderate',notes:'Steady conversational pace.'},
      {id:cryptoId(),day:6,name:'Rest Day',type:'Recovery',duration:15,intensity:'Low',notes:'Light stretching and recovery.'}
    ];
  }

  function cryptoId(){
    return 'w_'+Date.now().toString(36)+'_'+Math.random().toString(36).slice(2,8);
  }

  function loadAll(){
    return JSON.parse(localStorage.getItem(storageKey)||'{}');
  }

  function saveAll(data){
    localStorage.setItem(storageKey,JSON.stringify(data));
  }

  function loadWeek(){
    const all = loadAll();
    if(!all[weekKey()]){
      all[weekKey()] = weekOffset===0 ? defaultWeek() : [];
      saveAll(all);
    }
    return all[weekKey()];
  }

  function saveWeek(items){
    const all=loadAll();
    all[weekKey()]=items;
    saveAll(all);
  }

  function loadTemplates(){
    const saved=JSON.parse(localStorage.getItem(templateKey)||'null');
    if(saved) return saved;
    const defaults=[
      {id:'tpl_strength',name:'Full Body Strength',type:'Strength',duration:45,intensity:'Moderate',notes:'Balanced strength session.'},
      {id:'tpl_hiit',name:'Quick HIIT',type:'HIIT',duration:20,intensity:'High',notes:'Fast full-body conditioning.'},
      {id:'tpl_mobility',name:'Mobility Reset',type:'Mobility',duration:15,intensity:'Low',notes:'Gentle range-of-motion work.'},
      {id:'tpl_walk',name:'Brisk Walk',type:'Outdoor',duration:30,intensity:'Moderate',notes:'Purposeful outdoor walk.'}
    ];
    localStorage.setItem(templateKey,JSON.stringify(defaults));
    return defaults;
  }

  function formatRange(){
    const start=weekStart();
    const end=addDays(start,6);
    const options={month:'short',day:'numeric'};
    refs.weekRange.textContent=`${start.toLocaleDateString(undefined,options)} – ${end.toLocaleDateString(undefined,{...options,year:'numeric'})}`;
    refs.weekLabel.textContent=weekOffset===0?'This week':weekOffset===1?'Next week':weekOffset===-1?'Last week':`Week ${weekOffset>0?'+'+weekOffset:weekOffset}`;
  }

  function itemMarkup(item){
    return `<article class="planner-workout-card" draggable="true" data-id="${item.id}">
      <div class="planner-workout-icon">${typeIcons[item.type]||'🏋️'}</div>
      <div class="planner-workout-copy">
        <strong>${escapeHtml(item.name)}</strong>
        <span>${escapeHtml(item.type)} · ${item.duration} min · ${escapeHtml(item.intensity)}</span>
      </div>
      <button type="button" class="planner-card-menu" data-edit-id="${item.id}" aria-label="Edit workout">•••</button>
    </article>`;
  }

  function renderWeek(){
    formatRange();
    const items=loadWeek();
    refs.weekGrid.innerHTML=dayNames.map((day,index)=>{
      const date=addDays(weekStart(),index);
      const dayItems=items.filter(item=>item.day===index);
      return `<section class="planner-day-column" data-day="${index}">
        <header>
          <div>
            <span>${shortDays[index]}</span>
            <strong>${date.getDate()}</strong>
          </div>
          <button type="button" data-add-day="${index}" aria-label="Add workout">+</button>
        </header>
        <div class="planner-day-dropzone" data-day="${index}">
          ${dayItems.length?dayItems.map(itemMarkup).join(''):'<div class="planner-empty-day">Rest or add workout</div>'}
        </div>
      </section>`;
    }).join('');

    bindWeekEvents();
  }

  function bindWeekEvents(){
    refs.weekGrid.querySelectorAll('[data-add-day]').forEach(btn=>{
      btn.addEventListener('click',()=>openModal(null,Number(btn.dataset.addDay)));
    });

    refs.weekGrid.querySelectorAll('[data-edit-id]').forEach(btn=>{
      btn.addEventListener('click',()=>openModal(btn.dataset.editId));
    });

    refs.weekGrid.querySelectorAll('.planner-workout-card').forEach(card=>{
      card.addEventListener('dragstart',()=>{
        draggedId=card.dataset.id;
        card.classList.add('is-dragging');
      });
      card.addEventListener('dragend',()=>{
        draggedId=null;
        card.classList.remove('is-dragging');
      });
    });

    refs.weekGrid.querySelectorAll('.planner-day-dropzone').forEach(zone=>{
      zone.addEventListener('dragover',event=>{
        event.preventDefault();
        zone.classList.add('is-drag-over');
      });
      zone.addEventListener('dragleave',()=>zone.classList.remove('is-drag-over'));
      zone.addEventListener('drop',event=>{
        event.preventDefault();
        zone.classList.remove('is-drag-over');
        if(!draggedId) return;
        const items=loadWeek();
        const item=items.find(x=>x.id===draggedId);
        if(item){
          item.day=Number(zone.dataset.day);
          saveWeek(items);
          renderWeek();
        }
      });
    });
  }

  function renderTemplates(){
    const templates=loadTemplates();
    refs.templates.innerHTML=templates.map(t=>`
      <article class="planner-template-card">
        <div class="planner-template-icon">${typeIcons[t.type]||'🏋️'}</div>
        <div>
          <strong>${escapeHtml(t.name)}</strong>
          <span>${escapeHtml(t.type)} · ${t.duration} min</span>
        </div>
        <button type="button" data-use-template="${t.id}">Add</button>
      </article>
    `).join('');

    refs.templates.querySelectorAll('[data-use-template]').forEach(btn=>{
      btn.addEventListener('click',()=>{
        const template=templates.find(t=>t.id===btn.dataset.useTemplate);
        if(template) openModal({...template,id:''},0);
      });
    });
  }

  function escapeHtml(value){
    return String(value??'').replace(/[&<>"']/g,ch=>({
      '&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'
    })[ch]);
  }

  function populateDays(){
    refs.day.innerHTML=dayNames.map((name,i)=>`<option value="${i}">${name}</option>`).join('');
  }

  function openModal(itemOrId=null,forcedDay=null){
    const items=loadWeek();
    let item=null;

    if(typeof itemOrId==='string' && itemOrId){
      item=items.find(x=>x.id===itemOrId)||null;
    }else if(itemOrId && typeof itemOrId==='object'){
      item=itemOrId;
    }

    refs.form.reset();
    refs.editId.value=item?.id||'';
    refs.name.value=item?.name||'';
    refs.day.value=String(forcedDay ?? item?.day ?? 0);
    refs.type.value=item?.type||'Strength';
    refs.duration.value=String(item?.duration||30);
    refs.intensity.value=item?.intensity||'Moderate';
    refs.notes.value=item?.notes||'';
    refs.title.textContent=item?.id?'Edit workout':'Create workout';
    refs.deleteBtn.hidden=!item?.id;
    refs.modal.hidden=false;
    document.body.classList.add('planner-modal-open');
    setTimeout(()=>refs.name.focus(),50);
  }

  function closeModal(){
    refs.modal.hidden=true;
    document.body.classList.remove('planner-modal-open');
  }

  refs.form.addEventListener('submit',event=>{
    event.preventDefault();
    const items=loadWeek();
    const id=refs.editId.value;
    const workout={
      id:id||cryptoId(),
      day:Number(refs.day.value),
      name:refs.name.value.trim(),
      type:refs.type.value,
      duration:Number(refs.duration.value),
      intensity:refs.intensity.value,
      notes:refs.notes.value.trim()
    };

    if(id){
      const index=items.findIndex(x=>x.id===id);
      if(index>=0) items[index]=workout;
    }else{
      items.push(workout);
    }

    saveWeek(items);
    closeModal();
    renderWeek();
  });

  refs.deleteBtn.addEventListener('click',()=>{
    const id=refs.editId.value;
    if(!id) return;
    saveWeek(loadWeek().filter(x=>x.id!==id));
    closeModal();
    renderWeek();
  });

  document.querySelectorAll('[data-close-planner-modal]').forEach(el=>{
    el.addEventListener('click',closeModal);
  });

  refs.prev.addEventListener('click',()=>{weekOffset--;renderWeek();});
  refs.next.addEventListener('click',()=>{weekOffset++;renderWeek();});
  refs.create.addEventListener('click',()=>openModal());
  refs.reset.addEventListener('click',()=>{
    const all=loadAll();
    delete all[weekKey()];
    saveAll(all);
    renderWeek();
  });

  refs.auto.addEventListener('click',()=>{
    const plan=[
      {id:cryptoId(),day:0,name:'Full Body Strength',type:'Strength',duration:40,intensity:'Moderate',notes:'Compound movements and core.'},
      {id:cryptoId(),day:1,name:'Brisk Walk',type:'Outdoor',duration:30,intensity:'Moderate',notes:'Steady outdoor pace.'},
      {id:cryptoId(),day:2,name:'Mobility & Core',type:'Mobility',duration:25,intensity:'Low',notes:'Mobility, stability and posture.'},
      {id:cryptoId(),day:3,name:'Upper Body Strength',type:'Strength',duration:35,intensity:'Moderate',notes:'Push and pull emphasis.'},
      {id:cryptoId(),day:4,name:'Interval Cardio',type:'HIIT',duration:20,intensity:'High',notes:'Short work and recovery intervals.'},
      {id:cryptoId(),day:5,name:'Lower Body Strength',type:'Strength',duration:40,intensity:'Moderate',notes:'Legs, glutes and balance.'},
      {id:cryptoId(),day:6,name:'Recovery Day',type:'Recovery',duration:15,intensity:'Low',notes:'Gentle stretching and rest.'}
    ];
    saveWeek(plan);
    renderWeek();
  });

  refs.back.addEventListener('click',()=>{
    screen.hidden=true;
    const home=document.querySelector('.screen:not(#plannerScreen):not(#walkRunScreen)');
    if(home) home.hidden=false;
  });

  function openPlanner(){
    document.querySelectorAll('.screen').forEach(s=>s.hidden=true);
    screen.hidden=false;
    window.scrollTo({top:0,behavior:'smooth'});
    renderWeek();
    renderTemplates();
  }

  document.addEventListener('click',event=>{
    const el=event.target.closest('button,a,[data-screen],[data-page]');
    if(!el || el.closest('#plannerScreen')) return;
    const text=(el.textContent||'').trim().toLowerCase();
    const target=((el.dataset&&(`${el.dataset.screen||''} ${el.dataset.page||''}`))||'').toLowerCase();
    if(text.includes('planner') || text.includes('plan workout') || target.includes('planner')){
      event.preventDefault();
      openPlanner();
    }
  });

  populateDays();
  renderWeek();
  renderTemplates();
})();


/* =========================================================
   TOURAYS FITNESS V9 — PROGRESS & ANALYTICS
   ========================================================= */
(function(){
  const screen=document.getElementById('progressScreen');
  if(!screen) return;

  const $=id=>document.getElementById(id);
  const refs={
    back:$('progressBackBtn'),
    count:$('progressWorkoutCount'),
    delta:$('progressWorkoutDelta'),
    minutes:$('progressTrainingMinutes'),
    calories:$('progressCalories'),
    streak:$('progressStreak'),
    bars:$('progressBarChart'),
    chartSummary:$('progressChartSummary'),
    ring:$('progressGoalRing'),
    goalPercent:$('progressGoalPercent'),
    goalText:$('progressGoalText'),
    records:$('progressRecordsList'),
    currentWeight:$('progressCurrentWeight'),
    weightChange:$('progressWeightChange'),
    weightLine:$('progressWeightLine'),
    weightDots:$('progressWeightDots'),
    measurements:$('progressMeasurementHistory'),
    history:$('progressHistoryList'),
    clear:$('progressClearHistory'),
    workoutBtn:$('progressLogWorkout'),
    measurementBtn:$('progressAddMeasurement'),
    workoutModal:$('progressWorkoutModal'),
    workoutForm:$('progressWorkoutForm'),
    workoutName:$('progressWorkoutName'),
    workoutDate:$('progressWorkoutDate'),
    workoutType:$('progressWorkoutType'),
    workoutDuration:$('progressWorkoutDuration'),
    workoutCalories:$('progressWorkoutCalories'),
    workoutNotes:$('progressWorkoutNotes'),
    measurementModal:$('progressMeasurementModal'),
    measurementForm:$('progressMeasurementForm'),
    measurementDate:$('progressMeasurementDate'),
    measurementWeight:$('progressMeasurementWeight'),
    measurementWaist:$('progressMeasurementWaist'),
    measurementBodyFat:$('progressMeasurementBodyFat')
  };

  const workoutKey='touraysCompletedWorkoutsV1';
  const measurementKey='touraysBodyMeasurementsV1';
  let selectedRange=7;

  function uid(prefix='x'){
    return `${prefix}_${Date.now().toString(36)}_${Math.random().toString(36).slice(2,8)}`;
  }

  function loadWorkouts(){
    const manual=JSON.parse(localStorage.getItem(workoutKey)||'[]');
    const outdoor=(JSON.parse(localStorage.getItem('touraysWalkRunHistory')||'[]')).map(item=>({
      id:`outdoor_${item.id}`,
      name:item.mode==='run'?'Outdoor Run':'Outdoor Walk',
      type:'Outdoor',
      date:item.date,
      duration:Math.round((item.duration||0)/60000),
      calories:item.calories||0,
      distance:item.distance||0,
      source:'outdoor'
    }));
    const byId=new Map();
    [...manual,...outdoor].forEach(item=>byId.set(item.id,item));
    return [...byId.values()].sort((a,b)=>new Date(b.date)-new Date(a.date));
  }

  function saveWorkouts(items){
    const manual=items.filter(item=>item.source!=='outdoor');
    localStorage.setItem(workoutKey,JSON.stringify(manual));
  }

  function loadMeasurements(){
    return JSON.parse(localStorage.getItem(measurementKey)||'[]')
      .sort((a,b)=>new Date(a.date)-new Date(b.date));
  }

  function saveMeasurements(items){
    localStorage.setItem(measurementKey,JSON.stringify(items));
  }

  function rangeStart(days){
    const d=new Date();
    d.setHours(0,0,0,0);
    d.setDate(d.getDate()-(days-1));
    return d;
  }

  function filteredWorkouts(){
    const start=rangeStart(selectedRange);
    return loadWorkouts().filter(item=>new Date(item.date)>=start);
  }

  function dayKey(date){
    const d=new Date(date);
    return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
  }

  function computeStreak(items){
    const days=new Set(items.map(item=>dayKey(item.date)));
    let cursor=new Date();
    cursor.setHours(0,0,0,0);
    if(!days.has(dayKey(cursor))){
      cursor.setDate(cursor.getDate()-1);
    }
    let streak=0;
    while(days.has(dayKey(cursor))){
      streak++;
      cursor.setDate(cursor.getDate()-1);
    }
    return streak;
  }

  function escapeHtml(value){
    return String(value??'').replace(/[&<>"']/g,ch=>({
      '&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'
    })[ch]);
  }

  function renderKpis(){
    const all=loadWorkouts();
    const items=filteredWorkouts();
    const totalMinutes=items.reduce((sum,item)=>sum+(Number(item.duration)||0),0);
    const totalCalories=items.reduce((sum,item)=>sum+(Number(item.calories)||0),0);

    refs.count.textContent=items.length;
    refs.minutes.textContent=totalMinutes;
    refs.calories.textContent=Math.round(totalCalories);
    refs.streak.textContent=computeStreak(all);

    const previousStart=new Date(rangeStart(selectedRange));
    previousStart.setDate(previousStart.getDate()-selectedRange);
    const currentStart=rangeStart(selectedRange);
    const previousCount=all.filter(item=>{
      const d=new Date(item.date);
      return d>=previousStart && d<currentStart;
    }).length;

    const diff=items.length-previousCount;
    refs.delta.textContent=diff===0?'Same as previous period':`${diff>0?'+':''}${diff} vs previous period`;
  }

  function renderBars(){
    const items=filteredWorkouts();
    const days=Math.min(selectedRange,14);
    const start=rangeStart(days);
    const buckets=[];

    for(let i=0;i<days;i++){
      const date=new Date(start);
      date.setDate(start.getDate()+i);
      const key=dayKey(date);
      const minutes=items.filter(item=>dayKey(item.date)===key)
        .reduce((sum,item)=>sum+(Number(item.duration)||0),0);
      buckets.push({
        label:date.toLocaleDateString(undefined,{weekday:'short'}),
        date:date.getDate(),
        minutes
      });
    }

    const max=Math.max(30,...buckets.map(x=>x.minutes));
    refs.bars.innerHTML=buckets.map(bucket=>`
      <div class="progress-bar-column">
        <div class="progress-bar-track">
          <div class="progress-bar-fill" style="height:${Math.max(4,(bucket.minutes/max)*100)}%">
            <span>${bucket.minutes||''}</span>
          </div>
        </div>
        <strong>${bucket.label}</strong>
        <small>${bucket.date}</small>
      </div>
    `).join('');

    refs.chartSummary.textContent=`${buckets.reduce((s,x)=>s+x.minutes,0)} min`;
  }

  function renderGoal(){
    const weekStart=new Date();
    const day=weekStart.getDay();
    weekStart.setDate(weekStart.getDate()-day+(day===0?-6:1));
    weekStart.setHours(0,0,0,0);

    const weekCount=loadWorkouts().filter(item=>new Date(item.date)>=weekStart).length;
    const settings=JSON.parse(localStorage.getItem('touraysAutosaveSettings')||'{}');
    const target=Math.max(1,Number(settings.weeklyGoal||settings.profileWeeklyGoal||4));
    const percent=Math.min(100,Math.round((weekCount/target)*100));

    refs.ring.style.setProperty('--goal-progress',`${percent*3.6}deg`);
    refs.goalPercent.textContent=`${percent}%`;
    refs.goalText.textContent=`${weekCount} of ${target} workouts`;
  }

  function renderRecords(){
    const items=loadWorkouts();
    const outdoor=items.filter(item=>item.type==='Outdoor');
    const longest=items.reduce((best,item)=>(Number(item.duration)||0)>(Number(best?.duration)||0)?item:best,null);
    const calorieBest=items.reduce((best,item)=>(Number(item.calories)||0)>(Number(best?.calories)||0)?item:best,null);
    const longestDistance=outdoor.reduce((best,item)=>(Number(item.distance)||0)>(Number(best?.distance)||0)?item:best,null);
    const total=items.length;

    const records=[
      {icon:'⏱️',label:'Longest workout',value:longest?`${longest.duration} min`:'--'},
      {icon:'🔥',label:'Most calories',value:calorieBest?`${Math.round(calorieBest.calories)} kcal`:'--'},
      {icon:'🏃',label:'Longest distance',value:longestDistance?`${Number(longestDistance.distance).toFixed(2)} km`:'--'},
      {icon:'🏆',label:'Total sessions',value:String(total)}
    ];

    refs.records.innerHTML=records.map(record=>`
      <article>
        <span>${record.icon}</span>
        <div>
          <small>${record.label}</small>
          <strong>${record.value}</strong>
        </div>
      </article>
    `).join('');
  }

  function renderWeight(){
    const items=loadMeasurements();
    if(!items.length){
      refs.currentWeight.textContent='--';
      refs.weightChange.textContent='--';
      refs.weightLine.setAttribute('points','');
      refs.weightDots.innerHTML='';
      refs.measurements.innerHTML='<div class="progress-empty">No body measurements yet.</div>';
      return;
    }

    const current=items[items.length-1];
    const first=items[0];
    const change=Number(current.weight)-Number(first.weight);

    refs.currentWeight.textContent=Number(current.weight).toFixed(1);
    refs.weightChange.textContent=`${change>0?'+':''}${change.toFixed(1)} kg`;

    const recent=items.slice(-10);
    const weights=recent.map(x=>Number(x.weight));
    const min=Math.min(...weights);
    const max=Math.max(...weights);
    const range=max-min||1;

    const points=recent.map((item,index)=>{
      const x=recent.length===1?50:(index/(recent.length-1))*92+4;
      const y=44-((Number(item.weight)-min)/range)*36;
      return {x,y,item};
    });

    refs.weightLine.setAttribute('points',points.map(p=>`${p.x},${p.y}`).join(' '));
    refs.weightDots.innerHTML=points.map(p=>`<circle cx="${p.x}" cy="${p.y}" r="1.8"></circle>`).join('');

    refs.measurements.innerHTML=recent.slice().reverse().map(item=>`
      <article>
        <div>
          <strong>${Number(item.weight).toFixed(1)} kg</strong>
          <span>${new Date(item.date).toLocaleDateString()}</span>
        </div>
        <div>
          <small>Waist</small>
          <strong>${item.waist?`${Number(item.waist).toFixed(1)} cm`:'--'}</strong>
        </div>
        <div>
          <small>Body fat</small>
          <strong>${item.bodyFat?`${Number(item.bodyFat).toFixed(1)}%`:'--'}</strong>
        </div>
      </article>
    `).join('');
  }

  function renderHistory(){
    const items=filteredWorkouts();
    if(!items.length){
      refs.history.innerHTML='<div class="progress-empty">No workouts in this period.</div>';
      return;
    }

    refs.history.innerHTML=items.map(item=>`
      <article class="progress-history-item">
        <div class="progress-history-icon">${item.type==='Outdoor'?'🏃':item.type==='Strength'?'🏋️':item.type==='HIIT'?'⚡':item.type==='Mobility'?'🧘':'❤️'}</div>
        <div class="progress-history-copy">
          <strong>${escapeHtml(item.name)}</strong>
          <span>${new Date(item.date).toLocaleDateString()} · ${escapeHtml(item.type||'Workout')}</span>
        </div>
        <div class="progress-history-stats">
          <strong>${Number(item.duration)||0} min</strong>
          <span>${Math.round(Number(item.calories)||0)} kcal${item.distance?` · ${Number(item.distance).toFixed(2)} km`:''}</span>
        </div>
      </article>
    `).join('');
  }

  function renderAll(){
    renderKpis();
    renderBars();
    renderGoal();
    renderRecords();
    renderWeight();
    renderHistory();
  }

  function openModal(modal){
    modal.hidden=false;
    document.body.classList.add('planner-modal-open');
  }

  function closeModal(modal){
    modal.hidden=true;
    document.body.classList.remove('planner-modal-open');
  }

  refs.workoutBtn.addEventListener('click',()=>{
    refs.workoutForm.reset();
    refs.workoutDate.value=new Date().toISOString().slice(0,10);
    refs.workoutDuration.value=30;
    refs.workoutCalories.value=220;
    openModal(refs.workoutModal);
  });

  refs.measurementBtn.addEventListener('click',()=>{
    refs.measurementForm.reset();
    refs.measurementDate.value=new Date().toISOString().slice(0,10);
    const saved=JSON.parse(localStorage.getItem('touraysAutosaveSettings')||'{}');
    if(saved.weight||saved.profileWeight){
      refs.measurementWeight.value=saved.weight||saved.profileWeight;
    }
    openModal(refs.measurementModal);
  });

  document.querySelectorAll('[data-close-progress-workout]').forEach(el=>{
    el.addEventListener('click',()=>closeModal(refs.workoutModal));
  });
  document.querySelectorAll('[data-close-progress-measurement]').forEach(el=>{
    el.addEventListener('click',()=>closeModal(refs.measurementModal));
  });

  refs.workoutForm.addEventListener('submit',event=>{
    event.preventDefault();
    const items=loadWorkouts().filter(item=>item.source!=='outdoor');
    items.unshift({
      id:uid('workout'),
      name:refs.workoutName.value.trim(),
      type:refs.workoutType.value,
      date:new Date(`${refs.workoutDate.value}T12:00:00`).toISOString(),
      duration:Number(refs.workoutDuration.value),
      calories:Number(refs.workoutCalories.value)||0,
      notes:refs.workoutNotes.value.trim()
    });
    saveWorkouts(items);
    closeModal(refs.workoutModal);
    renderAll();
  });

  refs.measurementForm.addEventListener('submit',event=>{
    event.preventDefault();
    const items=loadMeasurements();
    items.push({
      id:uid('measure'),
      date:new Date(`${refs.measurementDate.value}T12:00:00`).toISOString(),
      weight:Number(refs.measurementWeight.value),
      waist:refs.measurementWaist.value?Number(refs.measurementWaist.value):null,
      bodyFat:refs.measurementBodyFat.value?Number(refs.measurementBodyFat.value):null
    });
    saveMeasurements(items);
    closeModal(refs.measurementModal);
    renderAll();
  });

  refs.clear.addEventListener('click',()=>{
    localStorage.removeItem(workoutKey);
    renderAll();
  });

  document.querySelectorAll('.progress-range').forEach(btn=>{
    btn.addEventListener('click',()=>{
      document.querySelectorAll('.progress-range').forEach(x=>x.classList.remove('active'));
      btn.classList.add('active');
      selectedRange=Number(btn.dataset.range);
      renderAll();
    });
  });

  refs.back.addEventListener('click',()=>{
    screen.hidden=true;
    const home=document.querySelector('.screen:not(#progressScreen):not(#plannerScreen):not(#walkRunScreen)');
    if(home) home.hidden=false;
  });

  function openProgress(){
    document.querySelectorAll('.screen').forEach(s=>s.hidden=true);
    screen.hidden=false;
    window.scrollTo({top:0,behavior:'smooth'});
    renderAll();
  }

  document.addEventListener('click',event=>{
    const el=event.target.closest('button,a,[data-screen],[data-page]');
    if(!el || el.closest('#progressScreen')) return;
    const text=(el.textContent||'').trim().toLowerCase();
    const target=((el.dataset&&(`${el.dataset.screen||''} ${el.dataset.page||''}`))||'').toLowerCase();
    if(text.includes('progress') || text.includes('analytics') || text.includes('statistics') || target.includes('progress') || target.includes('analytics')){
      event.preventDefault();
      openProgress();
    }
  });

  renderAll();
})();


/* =========================================================
   TOURAYS FITNESS V9 — AI COACH
   ========================================================= */
(function(){
  const screen=document.getElementById('coachScreen');
  if(!screen) return;

  const $=id=>document.getElementById(id);
  const refs={
    back:$('coachBackBtn'),
    goal:$('coachGoal'),
    time:$('coachTime'),
    energy:$('coachEnergy'),
    location:$('coachLocation'),
    refresh:$('coachRefreshPlan'),
    greeting:$('coachGreeting'),
    headline:$('coachHeadline'),
    summary:$('coachSummary'),
    title:$('coachPlanTitle'),
    badge:$('coachPlanBadge'),
    focus:$('coachPlanFocus'),
    intensity:$('coachPlanIntensity'),
    calories:$('coachPlanCalories'),
    blocks:$('coachPlanBlocks'),
    save:$('coachSaveToPlanner'),
    start:$('coachStartWorkout'),
    consistency:$('coachConsistencyInsight'),
    recovery:$('coachRecoveryInsight'),
    goalInsight:$('coachGoalInsight'),
    messages:$('coachChatMessages'),
    chatForm:$('coachChatForm'),
    chatInput:$('coachChatInput')
  };

  const storageKey='touraysCoachPreferencesV1';
  let currentPlan=null;

  const planLibrary={
    general:{
      low:{title:'Mobility & Core Reset',focus:'Mobility & stability',intensity:'Low',factor:5.5},
      medium:{title:'Balanced Full Body',focus:'Strength & conditioning',intensity:'Moderate',factor:7.3},
      high:{title:'Full Body Power',focus:'Strength & performance',intensity:'High',factor:9.2}
    },
    fatloss:{
      low:{title:'Low-Impact Cardio Flow',focus:'Cardio & mobility',intensity:'Low',factor:6.0},
      medium:{title:'Fat-Burn Circuit',focus:'Conditioning & strength',intensity:'Moderate',factor:8.0},
      high:{title:'High-Energy HIIT',focus:'Intervals & calorie burn',intensity:'High',factor:10.0}
    },
    muscle:{
      low:{title:'Technique Strength Session',focus:'Controlled strength',intensity:'Low',factor:5.8},
      medium:{title:'Muscle Builder',focus:'Progressive strength',intensity:'Moderate',factor:7.0},
      high:{title:'Strength Overload',focus:'Heavy strength work',intensity:'High',factor:8.5}
    },
    endurance:{
      low:{title:'Easy Endurance Base',focus:'Aerobic recovery',intensity:'Low',factor:6.2},
      medium:{title:'Steady Endurance',focus:'Aerobic capacity',intensity:'Moderate',factor:8.1},
      high:{title:'Tempo Intervals',focus:'Speed endurance',intensity:'High',factor:10.2}
    },
    mobility:{
      low:{title:'Gentle Mobility Reset',focus:'Recovery & range',intensity:'Low',factor:4.2},
      medium:{title:'Mobility Strength Flow',focus:'Mobility & control',intensity:'Moderate',factor:5.8},
      high:{title:'Dynamic Mobility Power',focus:'Mobility & athletic control',intensity:'High',factor:7.0}
    }
  };

  function loadPrefs(){
    return JSON.parse(localStorage.getItem(storageKey)||'{}');
  }

  function savePrefs(){
    localStorage.setItem(storageKey,JSON.stringify({
      goal:refs.goal.value,
      time:refs.time.value,
      energy:refs.energy.value,
      location:refs.location.value
    }));
  }

  function restorePrefs(){
    const prefs=loadPrefs();
    ['goal','time','energy','location'].forEach(key=>{
      if(prefs[key] && refs[key]) refs[key].value=prefs[key];
    });

    const profile=JSON.parse(localStorage.getItem('touraysAutosaveSettings')||'{}');
    const profileGoal=(profile.profileGoal||'').toLowerCase();
    if(!prefs.goal){
      if(profileGoal.includes('muscle')) refs.goal.value='muscle';
      else if(profileGoal.includes('fat') || profileGoal.includes('lose')) refs.goal.value='fatloss';
      else if(profileGoal.includes('endurance')) refs.goal.value='endurance';
      else if(profileGoal.includes('mobility')) refs.goal.value='mobility';
    }
  }

  function loadRecentWorkouts(){
    const manual=JSON.parse(localStorage.getItem('touraysCompletedWorkoutsV1')||'[]');
    const outdoor=JSON.parse(localStorage.getItem('touraysWalkRunHistory')||'[]');
    return [...manual,...outdoor].sort((a,b)=>new Date(b.date)-new Date(a.date));
  }

  function buildBlocks(goal,energy,time,location){
    const duration=Number(time);
    const warmup=Math.max(3,Math.round(duration*.15));
    const cooldown=Math.max(3,Math.round(duration*.12));
    const main=Math.max(8,duration-warmup-cooldown);

    const focusMap={
      general:['Squat to reach','Push-up variation','Reverse lunge','Mountain climber'],
      fatloss:['Fast march','Squat thrust','Alternating lunge','Low-impact climber'],
      muscle:['Tempo squat','Push-up','Split squat','Plank shoulder tap'],
      endurance:['March or jog','Step-back lunge','Skater step','Fast feet'],
      mobility:['World’s greatest stretch','Deep squat hold','Thoracic rotation','Hip flow']
    };

    const locationNote={
      home:'No equipment required',
      gym:'Use available machines or weights',
      outdoor:'Use open space and a steady route',
      anywhere:'Adapt movements to your surroundings'
    }[location];

    return [
      {label:'Warm-up',minutes:warmup,detail:'Raise body temperature and prepare the joints.'},
      {label:'Main block',minutes:main,detail:`${focusMap[goal].join(' · ')}. ${locationNote}.`},
      {label:'Cooldown',minutes:cooldown,detail:'Slow breathing, stretch and recover.'}
    ];
  }

  function workoutCountThisWeek(){
    const items=loadRecentWorkouts();
    const start=new Date();
    const day=start.getDay();
    start.setDate(start.getDate()-day+(day===0?-6:1));
    start.setHours(0,0,0,0);
    return items.filter(item=>new Date(item.date)>=start).length;
  }

  function generatePlan(){
    savePrefs();
    const goal=refs.goal.value;
    const energy=refs.energy.value;
    const time=Number(refs.time.value);
    const location=refs.location.value;
    const base=planLibrary[goal][energy];
    const settings=JSON.parse(localStorage.getItem('touraysAutosaveSettings')||'{}');
    const weight=Number(settings.weight||settings.profileWeight||75);
    const calories=Math.max(60,Math.round(base.factor*weight*(time/60)));
    const blocks=buildBlocks(goal,energy,time,location);

    currentPlan={
      id:`coach_${Date.now()}`,
      name:base.title,
      type:goal==='endurance'?'Cardio':goal==='mobility'?'Mobility':goal==='fatloss'?'HIIT':'Strength',
      duration:time,
      intensity:base.intensity,
      notes:blocks.map(x=>`${x.label}: ${x.detail}`).join(' '),
      focus:base.focus,
      calories,
      location
    };

    refs.title.textContent=base.title;
    refs.badge.textContent=`${time} min`;
    refs.focus.textContent=base.focus;
    refs.intensity.textContent=base.intensity;
    refs.calories.textContent=`${calories} kcal`;
    refs.headline.textContent=`${base.title} fits your day.`;
    refs.summary.textContent=`A ${base.intensity.toLowerCase()} ${time}-minute session designed for ${base.focus.toLowerCase()} at ${location}.`;

    refs.blocks.innerHTML=blocks.map((block,index)=>`
      <article class="coach-plan-block">
        <div class="coach-block-number">${index+1}</div>
        <div>
          <strong>${block.label}</strong>
          <span>${block.detail}</span>
        </div>
        <small>${block.minutes} min</small>
      </article>
    `).join('');

    const weekCount=workoutCountThisWeek();
    refs.consistency.textContent=weekCount===0
      ? 'Your first session this week will restart your momentum.'
      : `You have completed ${weekCount} session${weekCount===1?'':'s'} this week. Keep the streak moving.`;

    refs.recovery.textContent=energy==='low'
      ? 'Low energy detected. Keep the session controlled and stop before form breaks down.'
      : energy==='high'
        ? 'Your energy is high. Use the intensity, but keep movement quality first.'
        : 'Your current energy supports a productive moderate session.';

    refs.goalInsight.textContent={
      general:'A balanced mix of strength, cardio and mobility will support your goal.',
      fatloss:'Consistency and total weekly activity matter more than one very hard session.',
      muscle:'Prioritize controlled repetitions, recovery and gradual progression.',
      endurance:'Build easy volume first, then add controlled intervals.',
      mobility:'Frequent short mobility sessions usually work better than rare long sessions.'
    }[goal];
  }

  function saveToPlanner(){
    if(!currentPlan) generatePlan();
    const all=JSON.parse(localStorage.getItem('touraysWorkoutPlannerV1')||'{}');
    const monday=new Date();
    const day=monday.getDay();
    monday.setDate(monday.getDate()-day+(day===0?-6:1));
    monday.setHours(0,0,0,0);
    const key=monday.toISOString().slice(0,10);
    if(!all[key]) all[key]=[];

    const targetDay=(new Date().getDay()+6)%7;
    all[key].push({
      id:`coachplan_${Date.now()}`,
      day:targetDay,
      name:currentPlan.name,
      type:currentPlan.type,
      duration:currentPlan.duration,
      intensity:currentPlan.intensity,
      notes:currentPlan.notes
    });

    localStorage.setItem('touraysWorkoutPlannerV1',JSON.stringify(all));
    refs.save.textContent='Saved ✓';
    setTimeout(()=>refs.save.textContent='Save to planner',1800);
  }

  function startWorkout(){
    if(!currentPlan) generatePlan();
    const message=`${currentPlan.name} is ready. Follow the three blocks and complete ${currentPlan.duration} minutes at ${currentPlan.intensity.toLowerCase()} intensity.`;
    addMessage(message,'ai');
    refs.messages.scrollIntoView({behavior:'smooth',block:'center'});
  }

  function addMessage(text,type){
    const article=document.createElement('article');
    article.className=`coach-message coach-message-${type}`;
    article.innerHTML=type==='ai'
      ? `<div class="coach-message-avatar">T</div><p>${escapeHtml(text)}</p>`
      : `<p>${escapeHtml(text)}</p>`;
    refs.messages.appendChild(article);
    refs.messages.scrollTop=refs.messages.scrollHeight;
  }

  function escapeHtml(value){
    return String(value??'').replace(/[&<>"']/g,ch=>({
      '&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'
    })[ch]);
  }

  function coachReply(message){
    const text=message.toLowerCase();
    if(text.includes('tired') || text.includes('low energy')){
      return 'Choose low intensity today. A short mobility, walking or core session is enough to protect consistency without forcing recovery.';
    }
    if(text.includes('short')){
      return 'Use 3 minutes to warm up, 10 minutes for a focused circuit and 2 minutes to cool down. Keep transitions quick and form controlled.';
    }
    if(text.includes('next') || text.includes('train')){
      return `Based on your selected goal, your next priority should be ${currentPlan?.focus?.toLowerCase()||'a balanced full-body session'}.`;
    }
    if(text.includes('consistency')){
      return 'Lower the minimum. Commit to starting for 10 minutes. Once you begin, continue only when your body feels ready.';
    }
    if(text.includes('pain') || text.includes('injury')){
      return 'Do not train through sharp, worsening or unexplained pain. Stop the movement and seek qualified medical guidance when needed.';
    }
    return 'Keep today simple: choose one clear goal, train with controlled form and finish with enough energy to recover well for the next session.';
  }

  refs.refresh.addEventListener('click',generatePlan);
  [refs.goal,refs.time,refs.energy,refs.location].forEach(el=>el.addEventListener('change',generatePlan));
  refs.save.addEventListener('click',saveToPlanner);
  refs.start.addEventListener('click',startWorkout);

  refs.chatForm.addEventListener('submit',event=>{
    event.preventDefault();
    const text=refs.chatInput.value.trim();
    if(!text) return;
    addMessage(text,'user');
    refs.chatInput.value='';
    setTimeout(()=>addMessage(coachReply(text),'ai'),250);
  });

  document.querySelectorAll('[data-coach-prompt]').forEach(btn=>{
    btn.addEventListener('click',()=>{
      const text=btn.dataset.coachPrompt;
      addMessage(text,'user');
      setTimeout(()=>addMessage(coachReply(text),'ai'),250);
    });
  });

  refs.back.addEventListener('click',()=>{
    screen.hidden=true;
    const home=document.querySelector('.screen:not(#coachScreen):not(#progressScreen):not(#plannerScreen):not(#walkRunScreen)');
    if(home) home.hidden=false;
  });

  function openCoach(){
    document.querySelectorAll('.screen').forEach(s=>s.hidden=true);
    screen.hidden=false;
    window.scrollTo({top:0,behavior:'smooth'});
    generatePlan();
  }

  document.addEventListener('click',event=>{
    const el=event.target.closest('button,a,[data-screen],[data-page]');
    if(!el || el.closest('#coachScreen')) return;
    const text=(el.textContent||'').trim().toLowerCase();
    const target=((el.dataset&&(`${el.dataset.screen||''} ${el.dataset.page||''}`))||'').toLowerCase();
    if(text.includes('ai coach') || text==='coach' || target.includes('coach')){
      event.preventDefault();
      openCoach();
    }
  });

  restorePrefs();
  generatePlan();
})();


/* =========================================================
   TOURAYS FITNESS V9 — NUTRITION
   ========================================================= */
(function(){
  const screen=document.getElementById('nutritionScreen');
  if(!screen) return;

  const $=id=>document.getElementById(id);
  const refs={
    back:$('nutritionBackBtn'),
    prev:$('nutritionPrevDay'),
    next:$('nutritionNextDay'),
    dayLabel:$('nutritionDayLabel'),
    dateLabel:$('nutritionDateLabel'),
    calorieRing:$('nutritionCalorieRing'),
    caloriesRemaining:$('nutritionCaloriesRemaining'),
    caloriesUsed:$('nutritionCaloriesUsed'),
    caloriesGoal:$('nutritionCaloriesGoal'),
    calorieStatus:$('nutritionCalorieStatus'),
    proteinUsed:$('nutritionProteinUsed'),
    proteinGoal:$('nutritionProteinGoal'),
    proteinBar:$('nutritionProteinBar'),
    carbsUsed:$('nutritionCarbsUsed'),
    carbsGoal:$('nutritionCarbsGoal'),
    carbsBar:$('nutritionCarbsBar'),
    fatUsed:$('nutritionFatUsed'),
    fatGoal:$('nutritionFatGoal'),
    fatBar:$('nutritionFatBar'),
    waterUsed:$('nutritionWaterUsed'),
    waterGoal:$('nutritionWaterGoal'),
    waterBar:$('nutritionWaterBar'),
    waterReset:$('nutritionWaterReset'),
    mealGroups:$('nutritionMealGroups'),
    addMeal:$('nutritionAddMeal'),
    coachInsight:$('nutritionCoachInsight'),
    smartBadge:$('nutritionSmartBadge'),
    signalGrid:$('nutritionSignalGrid'),
    weekBars:$('nutritionWeekBars'),
    weekScore:$('nutritionWeekScore'),
    daysLogged:$('nutritionDaysLogged'),
    avgCalories:$('nutritionAvgCalories'),
    goalsReached:$('nutritionGoalsReached'),
    editGoals:$('nutritionEditGoals'),
    goalCaloriesDisplay:$('nutritionGoalCaloriesDisplay'),
    goalProteinDisplay:$('nutritionGoalProteinDisplay'),
    goalWaterDisplay:$('nutritionGoalWaterDisplay'),
    foodModal:$('nutritionFoodModal'),
    foodForm:$('nutritionFoodForm'),
    foodName:$('nutritionFoodName'),
    mealType:$('nutritionMealType'),
    serving:$('nutritionServing'),
    foodCalories:$('nutritionFoodCalories'),
    foodProtein:$('nutritionFoodProtein'),
    foodCarbs:$('nutritionFoodCarbs'),
    foodFat:$('nutritionFoodFat'),
    goalsModal:$('nutritionGoalsModal'),
    goalsForm:$('nutritionGoalsForm'),
    goalCaloriesInput:$('nutritionGoalCaloriesInput'),
    goalProteinInput:$('nutritionGoalProteinInput'),
    goalCarbsInput:$('nutritionGoalCarbsInput'),
    goalFatInput:$('nutritionGoalFatInput'),
    goalWaterInput:$('nutritionGoalWaterInput')
  };

  const diaryKey='touraysNutritionDiaryV1';
  const goalsKey='touraysNutritionGoalsV1';
  let dayOffset=0;

  function localDateKey(date){
    const d=new Date(date);
    return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
  }

  function selectedDate(){
    const d=new Date();
    d.setHours(12,0,0,0);
    d.setDate(d.getDate()+dayOffset);
    return d;
  }

  function selectedKey(){
    return localDateKey(selectedDate());
  }

  function uid(){
    return `food_${Date.now().toString(36)}_${Math.random().toString(36).slice(2,8)}`;
  }

  function loadDiary(){
    return JSON.parse(localStorage.getItem(diaryKey)||'{}');
  }

  function saveDiary(data){
    localStorage.setItem(diaryKey,JSON.stringify(data));
  }

  function currentDay(){
    const diary=loadDiary();
    if(!diary[selectedKey()]) diary[selectedKey()]={foods:[],water:0};
    return diary[selectedKey()];
  }

  function saveCurrentDay(day){
    const diary=loadDiary();
    diary[selectedKey()]=day;
    saveDiary(diary);
  }

  function defaultGoals(){
    const profile=JSON.parse(localStorage.getItem('touraysAutosaveSettings')||'{}');
    const weight=Number(profile.weight||profile.profileWeight||75);
    const calories=Math.round(weight*29);
    return {
      calories:Math.min(3800,Math.max(1600,calories)),
      protein:Math.round(weight*1.8),
      carbs:Math.round(weight*3),
      fat:Math.round(weight*.9),
      water:Math.round(weight*35/100)*100
    };
  }

  function loadGoals(){
    const saved=JSON.parse(localStorage.getItem(goalsKey)||'null');
    if(saved) return saved;
    const goals=defaultGoals();
    localStorage.setItem(goalsKey,JSON.stringify(goals));
    return goals;
  }

  function saveGoals(goals){
    localStorage.setItem(goalsKey,JSON.stringify(goals));
  }

  function totals(day){
    return day.foods.reduce((sum,item)=>({
      calories:sum.calories+Number(item.calories||0),
      protein:sum.protein+Number(item.protein||0),
      carbs:sum.carbs+Number(item.carbs||0),
      fat:sum.fat+Number(item.fat||0)
    }),{calories:0,protein:0,carbs:0,fat:0});
  }

  function pct(value,goal){
    return Math.max(0,Math.min(100,Math.round((value/goal)*100)));
  }

  function escapeHtml(value){
    return String(value??'').replace(/[&<>"']/g,ch=>({
      '&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'
    })[ch]);
  }

  function updateDate(){
    const d=selectedDate();
    refs.dayLabel.textContent=dayOffset===0?'Today':dayOffset===-1?'Yesterday':dayOffset===1?'Tomorrow':d.toLocaleDateString(undefined,{weekday:'long'});
    refs.dateLabel.textContent=d.toLocaleDateString(undefined,{month:'long',day:'numeric',year:'numeric'});
  }

  function renderSummary(){
    const day=currentDay();
    const goals=loadGoals();
    const sum=totals(day);

    refs.caloriesUsed.textContent=Math.round(sum.calories);
    refs.caloriesGoal.textContent=goals.calories;
    refs.caloriesRemaining.textContent=Math.max(0,goals.calories-Math.round(sum.calories));
    refs.calorieRing.style.setProperty('--nutrition-progress',`${pct(sum.calories,goals.calories)*3.6}deg`);

    refs.proteinUsed.textContent=Math.round(sum.protein);
    refs.proteinGoal.textContent=goals.protein;
    refs.proteinBar.style.width=`${pct(sum.protein,goals.protein)}%`;

    refs.carbsUsed.textContent=Math.round(sum.carbs);
    refs.carbsGoal.textContent=goals.carbs;
    refs.carbsBar.style.width=`${pct(sum.carbs,goals.carbs)}%`;

    refs.fatUsed.textContent=Math.round(sum.fat);
    refs.fatGoal.textContent=goals.fat;
    refs.fatBar.style.width=`${pct(sum.fat,goals.fat)}%`;

    refs.waterUsed.textContent=day.water||0;
    refs.waterGoal.textContent=goals.water;
    refs.waterBar.style.width=`${pct(day.water||0,goals.water)}%`;

    refs.goalCaloriesDisplay.textContent=`${goals.calories} kcal`;
    refs.goalProteinDisplay.textContent=`${goals.protein} g`;
    refs.goalWaterDisplay.textContent=`${goals.water} ml`;

    if(sum.calories===0){
      refs.calorieStatus.textContent='Start logging meals to see your progress.';
      refs.coachInsight.textContent='Log your first meal to receive a daily nutrition recommendation.';
    }else if(sum.protein<goals.protein*.5 && sum.calories>goals.calories*.55){
      refs.calorieStatus.textContent='Calories are progressing, but protein is still low.';
      refs.coachInsight.textContent='Prioritize a lean protein source in your next meal, such as chicken, fish, eggs, yogurt, beans or tofu.';
    }else if(sum.calories>goals.calories){
      refs.calorieStatus.textContent='You have exceeded today’s calorie target.';
      refs.coachInsight.textContent='No need to overcorrect. Keep the next meal lighter, focus on vegetables and protein, and return to your normal plan tomorrow.';
    }else if(day.water<goals.water*.45){
      refs.calorieStatus.textContent='Nutrition is on track. Hydration needs attention.';
      refs.coachInsight.textContent='Drink water regularly instead of trying to catch up late in the day.';
    }else{
      refs.calorieStatus.textContent='You are progressing well toward today’s targets.';
      refs.coachInsight.textContent='Keep your next meal balanced with protein, vegetables or fruit, and a suitable carbohydrate source.';
    }
    renderSmartInsights(day,goals,sum);
    renderWeek();
  }

  function renderSmartInsights(day,goals,sum){
    if(!refs.signalGrid) return;
    const calPct=pct(sum.calories,goals.calories);
    const proteinPct=pct(sum.protein,goals.protein);
    const waterPct=pct(day.water||0,goals.water);
    const calorieMessage=sum.calories===0?'Log food to begin':sum.calories>goals.calories?'Above today’s target':`${Math.max(0,goals.calories-Math.round(sum.calories))} kcal remaining`;
    const proteinMessage=sum.protein===0?'Waiting for today’s meals':proteinPct>=90?'Target nearly reached':proteinPct>=55?'Good progress today':'Add a protein source';
    const waterMessage=`${waterPct}% of hydration goal`;
    refs.signalGrid.innerHTML=`
      <article class="${sum.calories>goals.calories?'is-warning':calPct>=70?'is-good':''}"><span>🔥</span><div><strong>Calories</strong><small>${calorieMessage}</small></div></article>
      <article class="${proteinPct>=85?'is-good':sum.calories>goals.calories*.55&&proteinPct<50?'is-warning':''}"><span>🥩</span><div><strong>Protein</strong><small>${proteinMessage}</small></div></article>
      <article class="${waterPct>=80?'is-good':waterPct<45?'is-warning':''}"><span>💧</span><div><strong>Hydration</strong><small>${waterMessage}</small></div></article>`;
    const balanced=(calPct>=70&&calPct<=110)+(proteinPct>=75)+(waterPct>=70);
    if(refs.smartBadge){
      refs.smartBadge.textContent=sum.calories===0?'Ready':balanced>=3?'Strong day':balanced>=2?'On track':'Needs attention';
      refs.smartBadge.dataset.state=balanced>=3?'good':balanced>=2?'steady':'attention';
    }
  }

  function renderWeek(){
    if(!refs.weekBars) return;
    const diary=loadDiary();
    const goals=loadGoals();
    const days=[];
    let logged=0,totalCalories=0,goalsReached=0;
    for(let i=6;i>=0;i--){
      const d=new Date(); d.setHours(12,0,0,0); d.setDate(d.getDate()-i);
      const key=localDateKey(d);
      const day=diary[key]||{foods:[],water:0};
      const sum=totals(day);
      const hasLog=(day.foods||[]).length>0 || Number(day.water||0)>0;
      if(hasLog){logged++; totalCalories+=sum.calories;}
      const calOk=sum.calories>=goals.calories*.8&&sum.calories<=goals.calories*1.1;
      const proteinOk=sum.protein>=goals.protein*.8;
      const waterOk=Number(day.water||0)>=goals.water*.8;
      if(hasLog && calOk && proteinOk && waterOk) goalsReached++;
      days.push({label:d.toLocaleDateString(undefined,{weekday:'narrow'}),cal:pct(sum.calories,goals.calories),protein:pct(sum.protein,goals.protein),water:pct(day.water||0,goals.water),hasLog});
    }
    refs.weekBars.innerHTML=days.map(item=>`<div class="nutrition-week-day ${item.hasLog?'has-log':''}" title="Calories ${item.cal}%, protein ${item.protein}%, water ${item.water}%">
      <div class="nutrition-week-columns"><i style="height:${Math.max(item.hasLog?8:3,item.cal)}%"></i><i style="height:${Math.max(item.hasLog?8:3,item.protein)}%"></i><i style="height:${Math.max(item.hasLog?8:3,item.water)}%"></i></div><span>${item.label}</span></div>`).join('');
    if(refs.weekScore) refs.weekScore.textContent=`${logged}/7`;
    if(refs.daysLogged) refs.daysLogged.textContent=logged;
    if(refs.avgCalories) refs.avgCalories.textContent=logged?Math.round(totalCalories/logged):0;
    if(refs.goalsReached) refs.goalsReached.textContent=goalsReached;
  }

  function renderAnalytics(){
    const bars=document.getElementById('nutritionTrendBars');
    if(!bars) return;
    const diary=loadDiary();
    const goals=loadGoals();
    const chip=document.getElementById('nutritionAnalyticsChip');
    const caption=document.getElementById('nutritionTrendCaption');
    const headline=document.getElementById('nutritionPersonalHeadline');
    const tip=document.getElementById('nutritionPersonalTip');
    const frequency=document.getElementById('nutritionFrequencyList');
    const weeks=[];
    let totalLoggedDays=0,totalCalories=0,totalProteinPct=0,totalWaterPct=0;
    const foodCounts=new Map();
    for(let block=3;block>=0;block--){
      let weekCalories=0,weekDays=0;
      for(let offset=block*7+6;offset>=block*7;offset--){
        const d=new Date(); d.setHours(12,0,0,0); d.setDate(d.getDate()-offset);
        const day=diary[localDateKey(d)]||{foods:[],water:0};
        const sum=totals(day);
        const hasLog=(day.foods||[]).length>0||Number(day.water||0)>0;
        if(hasLog){
          weekDays++; totalLoggedDays++; weekCalories+=sum.calories; totalCalories+=sum.calories;
          totalProteinPct+=pct(sum.protein,goals.protein); totalWaterPct+=pct(day.water||0,goals.water);
        }
        (day.foods||[]).forEach(item=>{
          const label=String(item.name||'').trim(); if(!label) return;
          const key=label.toLowerCase(); const current=foodCounts.get(key)||{name:label,count:0}; current.count++; foodCounts.set(key,current);
        });
      }
      weeks.push({avg:weekDays?weekCalories/weekDays:0,days:weekDays});
    }
    const max=Math.max(goals.calories,...weeks.map(w=>w.avg));
    bars.innerHTML=weeks.map(w=>`<i class="${w.days?'':'is-empty'}" style="height:${w.days?Math.max(8,Math.round(w.avg/max*100)):5}%" title="${w.days?Math.round(w.avg)+' average kcal':'No entries'}"></i>`).join('');
    if(caption) caption.textContent=totalLoggedDays?`${totalLoggedDays} logged day${totalLoggedDays===1?'':'s'} in 28 days`:'No recent entries';
    if(chip){chip.textContent=totalLoggedDays>=10?'Personalized':totalLoggedDays>=3?'Learning':'Building';chip.dataset.state=totalLoggedDays>=10?'ready':totalLoggedDays>=3?'steady':'';}
    const avgProtein=totalLoggedDays?totalProteinPct/totalLoggedDays:0;
    const avgWater=totalLoggedDays?totalWaterPct/totalLoggedDays:0;
    const avgCalories=totalLoggedDays?totalCalories/totalLoggedDays:0;
    if(totalLoggedDays<3){headline.textContent='Log a few meals';tip.textContent='Your recommendation will become more useful as your diary grows.';}
    else if(avgWater<55){headline.textContent='Make hydration automatic';tip.textContent='Your recent water consistency is the clearest opportunity. Use the quick-add buttons throughout the day.';}
    else if(avgProtein<60){headline.textContent='Anchor meals with protein';tip.textContent='Your recent entries suggest protein is the easiest target to improve. Add one reliable protein source to each main meal.';}
    else if(avgCalories>goals.calories*1.12){headline.textContent='Create a little more margin';tip.textContent='Recent logged days trend above your calorie goal. Smaller portions or lighter snacks can help without drastic restriction.';}
    else{headline.textContent='Keep the rhythm';tip.textContent='Your recent pattern is balanced. Focus on consistency rather than making large changes.';}
    const common=[...foodCounts.values()].sort((a,b)=>b.count-a.count||a.name.localeCompare(b.name)).slice(0,5);
    frequency.innerHTML=common.length?common.map(item=>`<button type="button" title="Logged ${item.count} times">${escapeHtml(item.name)} <small>${item.count}×</small></button>`).join(''):'<span class="nutrition-frequency-empty">No repeated foods yet</span>';
    frequency.querySelectorAll('button').forEach(btn=>btn.addEventListener('click',()=>openFoodModal()));
  }

  function renderMeals(){
    const day=currentDay();
    const mealNames=['Breakfast','Lunch','Dinner','Snack'];

    refs.mealGroups.innerHTML=mealNames.map(meal=>{
      const items=day.foods.filter(item=>item.meal===meal);
      const calories=items.reduce((sum,item)=>sum+Number(item.calories||0),0);

      return `<section class="nutrition-meal-group">
        <header>
          <div>
            <strong>${meal}</strong>
            <span>${Math.round(calories)} kcal</span>
          </div>
          <button type="button" data-add-meal-type="${meal}">+</button>
        </header>
        <div class="nutrition-food-list">
          ${items.length?items.map(item=>`
            <article class="nutrition-food-item">
              <div>
                <strong>${escapeHtml(item.name)}</strong>
                <span>${escapeHtml(item.serving)}</span>
              </div>
              <div class="nutrition-food-macros">
                <strong>${Math.round(item.calories)} kcal</strong>
                <span>P ${Math.round(item.protein)} · C ${Math.round(item.carbs)} · F ${Math.round(item.fat)}</span>
              </div>
              <button type="button" data-delete-food="${item.id}" aria-label="Delete food">✕</button>
            </article>
          `).join(''):'<div class="nutrition-empty-meal">No food added</div>'}
        </div>
      </section>`;
    }).join('');

    refs.mealGroups.querySelectorAll('[data-add-meal-type]').forEach(btn=>{
      btn.addEventListener('click',()=>openFoodModal(btn.dataset.addMealType));
    });

    refs.mealGroups.querySelectorAll('[data-delete-food]').forEach(btn=>{
      btn.addEventListener('click',()=>{
        const day=currentDay();
        day.foods=day.foods.filter(item=>item.id!==btn.dataset.deleteFood);
        saveCurrentDay(day);
        renderAll();
      });
    });
  }

  function renderAll(){
    updateDate();
    renderSummary();
    renderMeals();
    renderAnalytics();
  }

  function openModal(modal){
    modal.hidden=false;
    document.body.classList.add('planner-modal-open');
  }

  function closeModal(modal){
    modal.hidden=true;
    document.body.classList.remove('planner-modal-open');
  }

  function openFoodModal(meal='Breakfast'){
    refs.foodForm.reset();
    refs.mealType.value=meal;
    refs.foodCalories.value=350;
    refs.foodProtein.value=25;
    refs.foodCarbs.value=40;
    refs.foodFat.value=10;
    openModal(refs.foodModal);
    setTimeout(()=>refs.foodName.focus(),40);
  }

  refs.addMeal.addEventListener('click',()=>openFoodModal());
  refs.prev.addEventListener('click',()=>{dayOffset--;renderAll();});
  refs.next.addEventListener('click',()=>{dayOffset++;renderAll();});

  document.querySelectorAll('[data-water-add]').forEach(btn=>{
    btn.addEventListener('click',()=>{
      const day=currentDay();
      day.water=Number(day.water||0)+Number(btn.dataset.waterAdd);
      saveCurrentDay(day);
      renderSummary();
    });
  });

  refs.waterReset.addEventListener('click',()=>{
    const day=currentDay();
    day.water=0;
    saveCurrentDay(day);
    renderSummary();
  });

  document.querySelectorAll('[data-close-nutrition-food]').forEach(el=>{
    el.addEventListener('click',()=>closeModal(refs.foodModal));
  });
  document.querySelectorAll('[data-close-nutrition-goals]').forEach(el=>{
    el.addEventListener('click',()=>closeModal(refs.goalsModal));
  });

  refs.foodForm.addEventListener('submit',event=>{
    event.preventDefault();
    const day=currentDay();
    day.foods.push({
      id:uid(),
      meal:refs.mealType.value,
      name:refs.foodName.value.trim(),
      serving:refs.serving.value.trim(),
      calories:Number(refs.foodCalories.value)||0,
      protein:Number(refs.foodProtein.value)||0,
      carbs:Number(refs.foodCarbs.value)||0,
      fat:Number(refs.foodFat.value)||0
    });
    saveCurrentDay(day);
    closeModal(refs.foodModal);
    renderAll();
  });

  refs.editGoals.addEventListener('click',()=>{
    const goals=loadGoals();
    refs.goalCaloriesInput.value=goals.calories;
    refs.goalProteinInput.value=goals.protein;
    refs.goalCarbsInput.value=goals.carbs;
    refs.goalFatInput.value=goals.fat;
    refs.goalWaterInput.value=goals.water;
    openModal(refs.goalsModal);
  });

  refs.goalsForm.addEventListener('submit',event=>{
    event.preventDefault();
    saveGoals({
      calories:Number(refs.goalCaloriesInput.value),
      protein:Number(refs.goalProteinInput.value),
      carbs:Number(refs.goalCarbsInput.value),
      fat:Number(refs.goalFatInput.value),
      water:Number(refs.goalWaterInput.value)
    });
    closeModal(refs.goalsModal);
    renderAll();
  });

  refs.back.addEventListener('click',()=>{
    screen.hidden=true;
    const home=document.querySelector('.screen:not(#nutritionScreen):not(#coachScreen):not(#progressScreen):not(#plannerScreen):not(#walkRunScreen)');
    if(home) home.hidden=false;
  });

  function openNutrition(){
    document.querySelectorAll('.screen').forEach(s=>s.hidden=true);
    screen.hidden=false;
    window.scrollTo({top:0,behavior:'smooth'});
    renderAll();
  }

  document.addEventListener('click',event=>{
    const el=event.target.closest('button,a,[data-screen],[data-page]');
    if(!el || el.closest('#nutritionScreen')) return;
    const text=(el.textContent||'').trim().toLowerCase();
    const target=((el.dataset&&(`${el.dataset.screen||''} ${el.dataset.page||''}`))||'').toLowerCase();
    if(text.includes('nutrition') || text.includes('food diary') || target.includes('nutrition')){
      event.preventDefault();
      openNutrition();
    }
  });

  renderAll();
})();


/* =========================================================
   TOURAYS FITNESS V9 — PROFILE & SETTINGS STEP 1
   ========================================================= */
(function(){
  const screen=document.getElementById('profileSettingsScreen');
  if(!screen) return;

  const $=id=>document.getElementById(id);
  const refs={
    back:$('profileSettingsBackBtn'),
    form:$('profileSettingsForm'),
    avatar:$('profileAvatarPreview'),
    avatarInput:$('profileAvatarInput'),
    overviewName:$('profileOverviewName'),
    overviewGoal:$('profileOverviewGoal'),
    bmiValue:$('profileBmiValue'),
    bmrValue:$('profileBmrValue'),
    fullName:$('profileFullName'),
    birthDate:$('profileBirthDate'),
    gender:$('profileGender'),
    fitnessLevel:$('profileFitnessLevel'),
    height:$('profileHeight'),
    weight:$('profileWeight'),
    goalWeight:$('profileGoalWeight'),
    activityLevel:$('profileActivityLevel'),
    bmiDetail:$('profileBmiDetail'),
    bmiStatus:$('profileBmiStatus'),
    bmrDetail:$('profileBmrDetail'),
    tdeeDetail:$('profileTdeeDetail'),
    saveStatus:$('profileSaveStatus')
  };

  const key='touraysProfileSettingsV1';

  function load(){
    return JSON.parse(localStorage.getItem(key)||'{}');
  }

  function ageFromBirthDate(value){
    if(!value) return null;
    const birth=new Date(value);
    const today=new Date();
    let age=today.getFullYear()-birth.getFullYear();
    const m=today.getMonth()-birth.getMonth();
    if(m<0 || (m===0 && today.getDate()<birth.getDate())) age--;
    return age>0?age:null;
  }

  function goalLabel(value){
    return {
      general:'General fitness',
      fatloss:'Lose body fat',
      muscle:'Build muscle',
      endurance:'Improve endurance',
      mobility:'Improve mobility',
      maintain:'Maintain weight'
    }[value]||'General fitness';
  }

  function calculate(){
    const height=Number(refs.height.value);
    const weight=Number(refs.weight.value);
    const age=ageFromBirthDate(refs.birthDate.value);
    const gender=refs.gender.value;
    const activity=Number(refs.activityLevel.value||1.55);

    let bmi=null;
    if(height>0 && weight>0){
      bmi=weight/Math.pow(height/100,2);
    }

    let bmr=null;
    if(height>0 && weight>0 && age){
      if(gender==='male') bmr=10*weight+6.25*height-5*age+5;
      else if(gender==='female') bmr=10*weight+6.25*height-5*age-161;
      else bmr=10*weight+6.25*height-5*age-78;
    }

    const tdee=bmr?bmr*activity:null;

    refs.bmiValue.textContent=bmi?bmi.toFixed(1):'--';
    refs.bmiDetail.textContent=bmi?bmi.toFixed(1):'--';
    refs.bmrValue.textContent=bmr?Math.round(bmr):'--';
    refs.bmrDetail.textContent=bmr?Math.round(bmr):'--';
    refs.tdeeDetail.textContent=tdee?Math.round(tdee):'--';

    if(!bmi){
      refs.bmiStatus.textContent='Add height and weight';
    }else if(bmi<18.5){
      refs.bmiStatus.textContent='Below general healthy range';
    }else if(bmi<25){
      refs.bmiStatus.textContent='Within general healthy range';
    }else if(bmi<30){
      refs.bmiStatus.textContent='Above general healthy range';
    }else{
      refs.bmiStatus.textContent='High BMI range';
    }
  }

  function selectedGoal(){
    return document.querySelector('input[name="profileGoal"]:checked')?.value||'general';
  }

  function updateOverview(){
    const name=refs.fullName.value.trim()||'Tourays Fitness User';
    const goal=selectedGoal();
    refs.overviewName.textContent=name;
    refs.overviewGoal.textContent=goalLabel(goal);
    refs.avatar.textContent=(name.charAt(0)||'T').toUpperCase();
  }

  function save(){
    const data={
      fullName:refs.fullName.value.trim(),
      birthDate:refs.birthDate.value,
      gender:refs.gender.value,
      fitnessLevel:refs.fitnessLevel.value,
      height:Number(refs.height.value)||null,
      weight:Number(refs.weight.value)||null,
      goalWeight:Number(refs.goalWeight.value)||null,
      activityLevel:Number(refs.activityLevel.value)||1.55,
      goal:selectedGoal(),
      avatar:load().avatar||null
    };
    localStorage.setItem(key,JSON.stringify(data));

    const existing=JSON.parse(localStorage.getItem('touraysAutosaveSettings')||'{}');
    localStorage.setItem('touraysAutosaveSettings',JSON.stringify({
      ...existing,
      fullName:data.fullName,
      profileName:data.fullName,
      birthDate:data.birthDate,
      gender:data.gender,
      fitnessLevel:data.fitnessLevel,
      height:data.height,
      profileHeight:data.height,
      weight:data.weight,
      profileWeight:data.weight,
      goalWeight:data.goalWeight,
      profileGoal:data.goal,
      activityLevel:data.activityLevel
    }));

    refs.saveStatus.textContent='Profile saved successfully.';
    setTimeout(()=>refs.saveStatus.textContent='Changes are saved locally on this device.',1800);
  }

  function restore(){
    const data=load();
    refs.fullName.value=data.fullName||'';
    refs.birthDate.value=data.birthDate||'';
    refs.gender.value=data.gender||'';
    refs.fitnessLevel.value=data.fitnessLevel||'beginner';
    refs.height.value=data.height||'';
    refs.weight.value=data.weight||'';
    refs.goalWeight.value=data.goalWeight||'';
    refs.activityLevel.value=String(data.activityLevel||1.55);

    const goal=document.querySelector(`input[name="profileGoal"][value="${data.goal||'general'}"]`);
    if(goal) goal.checked=true;

    if(data.avatar){
      refs.avatar.style.backgroundImage=`url(${data.avatar})`;
      refs.avatar.classList.add('has-image');
      refs.avatar.textContent='';
    }

    updateOverview();
    calculate();
  }

  refs.form.addEventListener('submit',event=>{
    event.preventDefault();
    updateOverview();
    calculate();
    save();
  });

  [refs.fullName,refs.birthDate,refs.gender,refs.height,refs.weight,refs.activityLevel]
    .forEach(el=>el.addEventListener('input',()=>{
      updateOverview();
      calculate();
    }));

  document.querySelectorAll('input[name="profileGoal"]').forEach(el=>{
    el.addEventListener('change',updateOverview);
  });

  refs.avatarInput.addEventListener('change',event=>{
    const file=event.target.files?.[0];
    if(!file) return;
    if(file.size>2*1024*1024){
      refs.saveStatus.textContent='Please choose an image smaller than 2 MB.';
      return;
    }
    const reader=new FileReader();
    reader.onload=()=>{
      const data=load();
      data.avatar=reader.result;
      localStorage.setItem(key,JSON.stringify(data));
      refs.avatar.style.backgroundImage=`url(${reader.result})`;
      refs.avatar.classList.add('has-image');
      refs.avatar.textContent='';
      refs.saveStatus.textContent='Profile photo updated.';
    };
    reader.readAsDataURL(file);
  });

  refs.back.addEventListener('click',()=>{
    screen.hidden=true;
    const home=document.querySelector('.screen:not(#profileSettingsScreen):not(#nutritionScreen):not(#coachScreen):not(#progressScreen):not(#plannerScreen):not(#walkRunScreen)');
    if(home) home.hidden=false;
  });

  function openProfile(){
    show('profileSettingsScreen');
    restore();
  }


  restore();
})();


/* =========================================================
   TOURAYS FITNESS V9 — PROFILE STEP 2: TRAINING PREFERENCES
   ========================================================= */
(function(){
  const screen=document.getElementById('profileSettingsScreen');
  if(!screen || !document.getElementById('profileWorkoutDuration')) return;

  const $=id=>document.getElementById(id);
  const refs={
    form:$('profileSettingsForm'),
    duration:$('profileWorkoutDuration'),
    workoutTime:$('profileWorkoutTime'),
    location:$('profileTrainingLocation'),
    weeklyTarget:$('profileWeeklyTarget'),
    weeklySummary:$('profileWeeklyPlanSummary'),
    durationSummary:$('profileDurationSummary'),
    locationSummary:$('profileLocationSummary'),
    saveStatus:$('profileSaveStatus')
  };

  const profileKey='touraysProfileSettingsV1';
  const trainingKey='touraysTrainingPreferencesV1';

  function selectedValues(name){
    return [...document.querySelectorAll(`input[name="${name}"]:checked`)].map(el=>el.value);
  }

  function setSelectedValues(name, values){
    const selected=new Set((values||[]).map(String));
    document.querySelectorAll(`input[name="${name}"]`).forEach(el=>{
      el.checked=selected.has(el.value);
    });
  }

  function loadTraining(){
    return JSON.parse(localStorage.getItem(trainingKey)||'{}');
  }

  function locationLabel(value){
    return {
      home:'Home',
      gym:'Gym',
      outdoor:'Outdoor',
      mixed:'Mixed'
    }[value]||'Mixed';
  }

  function updateSummary(){
    refs.weeklySummary.textContent=`${refs.weeklyTarget.value} workout${refs.weeklyTarget.value==='1'?'':'s'}`;
    refs.durationSummary.textContent=`${refs.duration.value} minutes`;
    refs.locationSummary.textContent=locationLabel(refs.location.value);
  }

  function restoreTraining(){
    const saved=loadTraining();

    refs.duration.value=String(saved.duration||30);
    refs.workoutTime.value=saved.workoutTime||'evening';
    refs.location.value=saved.location||'mixed';
    refs.weeklyTarget.value=String(saved.weeklyTarget||3);

    setSelectedValues('profileWorkoutDay', saved.days?.length ? saved.days : ['1','3','5']);
    setSelectedValues('profileEquipment', saved.equipment?.length ? saved.equipment : ['bodyweight']);

    updateSummary();
  }

  function saveTraining(){
    const data={
      duration:Number(refs.duration.value)||30,
      workoutTime:refs.workoutTime.value,
      location:refs.location.value,
      weeklyTarget:Number(refs.weeklyTarget.value)||3,
      days:selectedValues('profileWorkoutDay'),
      equipment:selectedValues('profileEquipment')
    };

    localStorage.setItem(trainingKey,JSON.stringify(data));

    const profile=JSON.parse(localStorage.getItem(profileKey)||'{}');
    localStorage.setItem(profileKey,JSON.stringify({...profile,training:data}));

    const autosave=JSON.parse(localStorage.getItem('touraysAutosaveSettings')||'{}');
    localStorage.setItem('touraysAutosaveSettings',JSON.stringify({
      ...autosave,
      workoutDuration:data.duration,
      preferredWorkoutTime:data.workoutTime,
      trainingLocation:data.location,
      weeklyGoal:data.weeklyTarget,
      workoutDays:data.days,
      equipment:data.equipment
    }));

    updateSummary();
  }

  refs.form.addEventListener('submit',()=>{
    saveTraining();
  });

  [refs.duration,refs.workoutTime,refs.location,refs.weeklyTarget]
    .forEach(el=>el.addEventListener('change',updateSummary));

  document.querySelectorAll('input[name="profileWorkoutDay"], input[name="profileEquipment"]')
    .forEach(el=>el.addEventListener('change',()=>{
      const selectedDays=selectedValues('profileWorkoutDay').length;
      const target=Number(refs.weeklyTarget.value);
      if(selectedDays>0 && selectedDays!==target){
        refs.saveStatus.textContent=`You selected ${selectedDays} workout day${selectedDays===1?'':'s'} while your weekly target is ${target}.`;
      }else{
        refs.saveStatus.textContent='Changes are saved locally on this device.';
      }
    }));

  const observer=new MutationObserver(()=>{
    if(!screen.hidden) restoreTraining();
  });
  observer.observe(screen,{attributes:true,attributeFilter:['hidden']});

  restoreTraining();
})();


/* =========================================================
   TOURAYS FITNESS V9 — PROFILE STEP 3: NUTRITION SETTINGS
   ========================================================= */
(function(){
  const screen=document.getElementById('profileSettingsScreen');
  if(!screen || !document.getElementById('profileNutritionCalories')) return;

  const $=id=>document.getElementById(id);
  const refs={
    form:$('profileSettingsForm'),
    autoBtn:$('profileAutoNutritionBtn'),
    calories:$('profileNutritionCalories'),
    protein:$('profileNutritionProtein'),
    carbs:$('profileNutritionCarbs'),
    fat:$('profileNutritionFat'),
    water:$('profileNutritionWater'),
    mealFrequency:$('profileMealFrequency'),
    proteinCalories:$('profileProteinCalories'),
    carbCalories:$('profileCarbCalories'),
    fatCalories:$('profileFatCalories'),
    macroCalories:$('profileMacroCalories'),
    status:$('profileNutritionStatus'),
    explanation:$('profileNutritionExplanation'),
    saveStatus:$('profileSaveStatus')
  };

  const profileKey='touraysProfileSettingsV1';
  const nutritionKey='touraysNutritionGoalsV1';
  const settingsKey='touraysNutritionSettingsV1';

  function selectedMode(){
    return document.querySelector('input[name="profileNutritionMode"]:checked')?.value||'auto';
  }

  function setMode(value){
    const input=document.querySelector(`input[name="profileNutritionMode"][value="${value}"]`);
    if(input) input.checked=true;
  }

  function readProfile(){
    const profile=JSON.parse(localStorage.getItem(profileKey)||'{}');
    const auto=JSON.parse(localStorage.getItem('touraysAutosaveSettings')||'{}');
    return {
      ...auto,
      ...profile,
      height:Number(profile.height||auto.height||auto.profileHeight||0),
      weight:Number(profile.weight||auto.weight||auto.profileWeight||75),
      goal:profile.goal||auto.profileGoal||'general',
      gender:profile.gender||auto.gender||'',
      birthDate:profile.birthDate||auto.birthDate||'',
      activityLevel:Number(profile.activityLevel||auto.activityLevel||1.55)
    };
  }

  function getAge(value){
    if(!value) return 30;
    const birth=new Date(value);
    const now=new Date();
    let age=now.getFullYear()-birth.getFullYear();
    const m=now.getMonth()-birth.getMonth();
    if(m<0 || (m===0 && now.getDate()<birth.getDate())) age--;
    return Math.max(15,Math.min(100,age||30));
  }

  function calculateTargets(){
    const p=readProfile();
    const weight=Math.max(35,p.weight||75);
    const height=Math.max(130,p.height||175);
    const age=getAge(p.birthDate);
    let bmr;

    if(p.gender==='male') bmr=10*weight+6.25*height-5*age+5;
    else if(p.gender==='female') bmr=10*weight+6.25*height-5*age-161;
    else bmr=10*weight+6.25*height-5*age-78;

    let calories=bmr*(p.activityLevel||1.55);

    const goalAdjustments={
      fatloss:-400,
      muscle:250,
      maintain:0,
      endurance:150,
      mobility:0,
      general:0
    };
    calories+=goalAdjustments[p.goal]||0;
    calories=Math.round(Math.max(1400,Math.min(5000,calories))/10)*10;

    const proteinFactor={
      fatloss:2.0,
      muscle:2.0,
      endurance:1.7,
      mobility:1.5,
      maintain:1.6,
      general:1.6
    }[p.goal]||1.6;

    let protein=Math.round(weight*proteinFactor);
    let fat=Math.round(weight*.8);
    let carbs=Math.round((calories-(protein*4+fat*9))/4);

    if(carbs<80){
      carbs=80;
      fat=Math.max(35,Math.round((calories-(protein*4+carbs*4))/9));
    }

    const water=Math.round((weight*35)/100)*100;

    return {calories,protein,carbs,fat,water};
  }

  function applyTargets(targets){
    refs.calories.value=targets.calories;
    refs.protein.value=targets.protein;
    refs.carbs.value=targets.carbs;
    refs.fat.value=targets.fat;
    refs.water.value=targets.water;
    updateSummary();
  }

  function updateSummary(){
    const protein=Math.max(0,Number(refs.protein.value)||0);
    const carbs=Math.max(0,Number(refs.carbs.value)||0);
    const fat=Math.max(0,Number(refs.fat.value)||0);
    const targetCalories=Math.max(0,Number(refs.calories.value)||0);

    const proteinCalories=protein*4;
    const carbCalories=carbs*4;
    const fatCalories=fat*9;
    const total=proteinCalories+carbCalories+fatCalories;
    const difference=Math.abs(total-targetCalories);

    refs.proteinCalories.textContent=`${proteinCalories} kcal`;
    refs.carbCalories.textContent=`${carbCalories} kcal`;
    refs.fatCalories.textContent=`${fatCalories} kcal`;
    refs.macroCalories.textContent=`${total} kcal`;

    if(selectedMode()==='auto'){
      refs.status.textContent='Automatic targets are active.';
      refs.explanation.textContent='Targets use your saved body metrics, activity level and fitness goal.';
    }else if(difference<=80){
      refs.status.textContent='Manual targets are balanced.';
      refs.explanation.textContent='Your macro calories are close to the selected daily calorie target.';
    }else{
      refs.status.textContent='Check your manual targets.';
      refs.explanation.textContent=`Macro calories differ from the calorie target by ${difference} kcal.`;
    }

    const disabled=selectedMode()==='auto';
    [refs.calories,refs.protein,refs.carbs,refs.fat,refs.water].forEach(input=>{
      input.readOnly=disabled;
      input.closest('label')?.classList.toggle('profile-field-readonly',disabled);
    });
  }

  function saveNutrition(){
    const data={
      mode:selectedMode(),
      calories:Number(refs.calories.value)||2200,
      protein:Number(refs.protein.value)||150,
      carbs:Number(refs.carbs.value)||240,
      fat:Number(refs.fat.value)||70,
      water:Number(refs.water.value)||2500,
      mealFrequency:Number(refs.mealFrequency.value)||4
    };

    localStorage.setItem(settingsKey,JSON.stringify(data));
    localStorage.setItem(nutritionKey,JSON.stringify({
      calories:data.calories,
      protein:data.protein,
      carbs:data.carbs,
      fat:data.fat,
      water:data.water
    }));

    const profile=JSON.parse(localStorage.getItem(profileKey)||'{}');
    localStorage.setItem(profileKey,JSON.stringify({...profile,nutrition:data}));

    const autosave=JSON.parse(localStorage.getItem('touraysAutosaveSettings')||'{}');
    localStorage.setItem('touraysAutosaveSettings',JSON.stringify({
      ...autosave,
      nutritionMode:data.mode,
      calorieGoal:data.calories,
      proteinGoal:data.protein,
      carbsGoal:data.carbs,
      fatGoal:data.fat,
      waterGoal:data.water,
      mealFrequency:data.mealFrequency
    }));
  }

  function restoreNutrition(){
    const saved=JSON.parse(localStorage.getItem(settingsKey)||'null');

    if(saved){
      setMode(saved.mode||'auto');
      refs.calories.value=saved.calories||2200;
      refs.protein.value=saved.protein||150;
      refs.carbs.value=saved.carbs||240;
      refs.fat.value=saved.fat||70;
      refs.water.value=saved.water||2500;
      refs.mealFrequency.value=String(saved.mealFrequency||4);
    }else{
      setMode('auto');
      applyTargets(calculateTargets());
    }

    updateSummary();
  }

  refs.autoBtn.addEventListener('click',()=>{
    setMode('auto');
    applyTargets(calculateTargets());
    refs.saveStatus.textContent='Nutrition targets recalculated from your current profile.';
  });

  document.querySelectorAll('input[name="profileNutritionMode"]').forEach(input=>{
    input.addEventListener('change',()=>{
      if(selectedMode()==='auto') applyTargets(calculateTargets());
      else updateSummary();
    });
  });

  [refs.calories,refs.protein,refs.carbs,refs.fat,refs.water]
    .forEach(input=>input.addEventListener('input',updateSummary));

  refs.form.addEventListener('submit',()=>{
    saveNutrition();
  });

  const observer=new MutationObserver(()=>{
    if(!screen.hidden) restoreNutrition();
  });
  observer.observe(screen,{attributes:true,attributeFilter:['hidden']});

  restoreNutrition();
})();


/* =========================================================
   TOURAYS FITNESS V9 — PROFILE STEP 4: NOTIFICATIONS & APP PREFERENCES
   ========================================================= */
(function(){
  const screen=document.getElementById('profileSettingsScreen');
  if(!screen || !document.getElementById('profileWorkoutReminders')) return;

  const $=id=>document.getElementById(id);
  const refs={
    form:$('profileSettingsForm'),
    workoutReminders:$('profileWorkoutReminders'),
    waterReminders:$('profileWaterReminders'),
    mealReminders:$('profileMealReminders'),
    dailySummary:$('profileDailySummary'),
    weeklyReport:$('profileWeeklyReport'),
    achievementAlerts:$('profileAchievementAlerts'),
    workoutReminderTime:$('profileWorkoutReminderTime'),
    dailySummaryTime:$('profileDailySummaryTime'),
    notificationStatus:$('profileNotificationStatus'),
    theme:$('profileTheme'),
    countdown:$('profileCountdown'),
    voiceCoach:$('profileVoiceCoach'),
    gpsAccuracy:$('profileGpsAccuracy'),
    vibration:$('profileVibration'),
    soundEffects:$('profileSoundEffects'),
    autoPause:$('profileAutoPause'),
    keepAwake:$('profileKeepAwake'),
    themeSummary:$('profileThemeSummary'),
    countdownSummary:$('profileCountdownSummary'),
    voiceSummary:$('profileVoiceSummary')
  };

  const key='touraysNotificationPreferencesV1';
  const appKey='touraysAppPreferencesV1';

  function themeLabel(value){
    return {system:'System',light:'Light',dark:'Dark'}[value]||'System';
  }

  function applyTheme(value){
    document.documentElement.dataset.theme=value;
    if(value==='dark'){
      document.documentElement.classList.add('tourays-dark-theme');
    }else{
      document.documentElement.classList.remove('tourays-dark-theme');
    }
  }

  async function requestNotificationPermission(){
    if(!('Notification' in window)) {
      refs.notificationStatus.textContent='Browser notifications are not supported on this device.';
      return;
    }

    if(Notification.permission==='granted'){
      refs.notificationStatus.textContent='Browser notification permission is enabled.';
      return;
    }

    if(Notification.permission==='denied'){
      refs.notificationStatus.textContent='Notifications are blocked in the browser settings.';
      return;
    }

    try{
      const permission=await Notification.requestPermission();
      refs.notificationStatus.textContent=
        permission==='granted'
          ? 'Browser notification permission is enabled.'
          : 'Notification permission was not enabled.';
    }catch{
      refs.notificationStatus.textContent='Notification permission could not be requested.';
    }
  }

  function updateSummary(){
    refs.themeSummary.textContent=themeLabel(refs.theme.value);
    refs.countdownSummary.textContent=
      refs.countdown.value==='0' ? 'Off' : `${refs.countdown.value} seconds`;
    refs.voiceSummary.textContent=refs.voiceCoach.value==='on' ? 'On' : 'Off';
  }

  function savePreferences(){
    const notifications={
      workoutReminders:refs.workoutReminders.checked,
      waterReminders:refs.waterReminders.checked,
      mealReminders:refs.mealReminders.checked,
      dailySummary:refs.dailySummary.checked,
      weeklyReport:refs.weeklyReport.checked,
      achievementAlerts:refs.achievementAlerts.checked,
      workoutReminderTime:refs.workoutReminderTime.value||'18:00',
      dailySummaryTime:refs.dailySummaryTime.value||'20:30'
    };

    const preferences={
      theme:refs.theme.value,
      countdown:Number(refs.countdown.value),
      voiceCoach:refs.voiceCoach.value==='on',
      gpsAccuracy:refs.gpsAccuracy.value,
      vibration:refs.vibration.checked,
      soundEffects:refs.soundEffects.checked,
      autoPause:refs.autoPause.checked,
      keepAwake:refs.keepAwake.checked
    };

    localStorage.setItem(key,JSON.stringify(notifications));
    localStorage.setItem(appKey,JSON.stringify(preferences));

    const autosave=JSON.parse(localStorage.getItem('touraysAutosaveSettings')||'{}');
    localStorage.setItem('touraysAutosaveSettings',JSON.stringify({
      ...autosave,
      workoutReminders:notifications.workoutReminders,
      waterReminders:notifications.waterReminders,
      mealReminders:notifications.mealReminders,
      dailySummary:notifications.dailySummary,
      weeklyReport:notifications.weeklyReport,
      achievementAlerts:notifications.achievementAlerts,
      workoutReminderTime:notifications.workoutReminderTime,
      dailySummaryTime:notifications.dailySummaryTime,
      theme:preferences.theme,
      countdown:preferences.countdown,
      voice:preferences.voiceCoach,
      vibration:preferences.vibration,
      soundEffects:preferences.soundEffects,
      gpsAccuracy:preferences.gpsAccuracy,
      autoPause:preferences.autoPause,
      keepAwake:preferences.keepAwake
    }));

    applyTheme(preferences.theme);
    updateSummary();
  }

  function restorePreferences(){
    const notifications=JSON.parse(localStorage.getItem(key)||'{}');
    const preferences=JSON.parse(localStorage.getItem(appKey)||'{}');

    refs.workoutReminders.checked=notifications.workoutReminders!==false;
    refs.waterReminders.checked=Boolean(notifications.waterReminders);
    refs.mealReminders.checked=Boolean(notifications.mealReminders);
    refs.dailySummary.checked=notifications.dailySummary!==false;
    refs.weeklyReport.checked=notifications.weeklyReport!==false;
    refs.achievementAlerts.checked=notifications.achievementAlerts!==false;
    refs.workoutReminderTime.value=notifications.workoutReminderTime||'18:00';
    refs.dailySummaryTime.value=notifications.dailySummaryTime||'20:30';

    refs.theme.value=preferences.theme||'system';
    refs.countdown.value=String(preferences.countdown ?? 5);
    refs.voiceCoach.value=preferences.voiceCoach===false ? 'off' : 'on';
    refs.gpsAccuracy.value=preferences.gpsAccuracy||'balanced';
    refs.vibration.checked=preferences.vibration!==false;
    refs.soundEffects.checked=preferences.soundEffects!==false;
    refs.autoPause.checked=Boolean(preferences.autoPause);
    refs.keepAwake.checked=Boolean(preferences.keepAwake);

    applyTheme(refs.theme.value);
    updateSummary();

    if('Notification' in window){
      refs.notificationStatus.textContent=
        Notification.permission==='granted'
          ? 'Browser notification permission is enabled.'
          : 'Notifications are stored locally until browser permission is enabled.';
    }
  }

  [
    refs.workoutReminders,
    refs.waterReminders,
    refs.mealReminders,
    refs.dailySummary
  ].forEach(input=>{
    input.addEventListener('change',()=>{
      if(input.checked) requestNotificationPermission();
    });
  });

  [refs.theme,refs.countdown,refs.voiceCoach].forEach(input=>{
    input.addEventListener('change',()=>{
      if(input===refs.theme) applyTheme(refs.theme.value);
      updateSummary();
    });
  });

  refs.form.addEventListener('submit',()=>{
    savePreferences();
  });

  const observer=new MutationObserver(()=>{
    if(!screen.hidden) restorePreferences();
  });
  observer.observe(screen,{attributes:true,attributeFilter:['hidden']});

  restorePreferences();
})();


/* =========================================================
   TOURAYS FITNESS V9 — PROFILE STEP 5: DATA, PRIVACY & LOCALIZATION
   ========================================================= */
(function(){
  const screen=document.getElementById('profileSettingsScreen');
  if(!screen || !document.getElementById('profileExportDataBtn')) return;

  const $=id=>document.getElementById(id);
  const refs={
    form:$('profileSettingsForm'),
    language:$('profileLanguage'),
    unitSystem:$('profileUnitSystem'),
    distanceUnit:$('profileDistanceUnit'),
    temperatureUnit:$('profileTemperatureUnit'),
    weightUnitSummary:$('profileWeightUnitSummary'),
    distanceUnitSummary:$('profileDistanceUnitSummary'),
    temperatureUnitSummary:$('profileTemperatureUnitSummary'),
    exportBtn:$('profileExportDataBtn'),
    importInput:$('profileImportDataInput'),
    clearHistoryBtn:$('profileClearHistoryBtn'),
    resetBtn:$('profileResetAppBtn'),
    dataStatus:$('profileDataStatus'),
    dataDetails:$('profileDataDetails'),
    locationPermission:$('profileLocationPermission'),
    healthPermission:$('profileHealthDataPermission'),
    analyticsConsent:$('profileAnalyticsConsent'),
    offlineSupport:$('profileOfflineSupport')
  };

  const localizationKey='touraysLocalizationSettingsV1';
  const privacyKey='touraysPrivacySettingsV1';

  function localKeys(){
    const keys=[];
    for(let i=0;i<localStorage.length;i++){
      const key=localStorage.key(i);
      if(key && (
        key.toLowerCase().includes('tourays') ||
        key.toLowerCase().includes('workout') ||
        key.toLowerCase().includes('nutrition') ||
        key.toLowerCase().includes('planner') ||
        key.toLowerCase().includes('progress') ||
        key.toLowerCase().includes('walk')
      )) keys.push(key);
    }
    return [...new Set(keys)].sort();
  }

  function exportData(){
    const data={};
    localKeys().forEach(key=>{
      const raw=localStorage.getItem(key);
      try{ data[key]=JSON.parse(raw); }
      catch{ data[key]=raw; }
    });

    const backup={
      app:'Tourays Fitness',
      version:'V9.13',
      exportedAt:new Date().toISOString(),
      storage:data
    };

    const blob=new Blob([JSON.stringify(backup,null,2)],{type:'application/json'});
    const url=URL.createObjectURL(blob);
    const a=document.createElement('a');
    const stamp=new Date().toISOString().slice(0,10);
    a.href=url;
    a.download=`tourays-fitness-backup-${stamp}.json`;
    document.body.appendChild(a);
    a.click();
    a.remove();
    URL.revokeObjectURL(url);

    refs.dataStatus.textContent='Backup exported successfully.';
    refs.dataDetails.textContent=`${Object.keys(data).length} local data groups were included.`;
  }

  async function importData(file){
    if(!file) return;
    try{
      const text=await file.text();
      const backup=JSON.parse(text);
      if(!backup || typeof backup.storage!=='object'){
        throw new Error('Invalid backup format');
      }

      Object.entries(backup.storage).forEach(([key,value])=>{
        localStorage.setItem(key,typeof value==='string'?value:JSON.stringify(value));
      });

      refs.dataStatus.textContent='Backup imported successfully.';
      refs.dataDetails.textContent='Reloading the app to apply restored settings.';
      setTimeout(()=>location.reload(),900);
    }catch(error){
      refs.dataStatus.textContent='Backup import failed.';
      refs.dataDetails.textContent='Please select a valid Tourays Fitness JSON backup.';
    }
  }

  function clearWorkoutHistory(){
    const candidates=localKeys().filter(key=>{
      const lower=key.toLowerCase();
      return lower.includes('history') ||
             lower.includes('workoutlog') ||
             lower.includes('activitylog') ||
             lower.includes('walkrun') ||
             lower.includes('progressworkout');
    });

    if(!confirm(`Remove ${candidates.length} workout history data group${candidates.length===1?'':'s'}?`)) return;
    candidates.forEach(key=>localStorage.removeItem(key));

    refs.dataStatus.textContent='Workout history cleared.';
    refs.dataDetails.textContent='Profile, settings and nutrition targets were kept.';
  }

  function resetApp(){
    if(!confirm('Delete all Tourays Fitness data stored on this device? This cannot be undone.')) return;
    localKeys().forEach(key=>localStorage.removeItem(key));
    refs.dataStatus.textContent='Application data reset.';
    refs.dataDetails.textContent='Reloading Tourays Fitness with default settings.';
    setTimeout(()=>location.reload(),900);
  }

  function updateUnitSummary(){
    const metric=refs.unitSystem.value==='metric';
    if(metric){
      refs.distanceUnit.value='km';
      refs.temperatureUnit.value='c';
    }
    refs.weightUnitSummary.textContent=metric?'Kilograms':'Pounds';
    refs.distanceUnitSummary.textContent=refs.distanceUnit.value==='km'?'Kilometres':'Miles';
    refs.temperatureUnitSummary.textContent=refs.temperatureUnit.value==='c'?'Celsius':'Fahrenheit';
  }

  function saveSettings(){
    const localization={
      language:refs.language.value,
      unitSystem:refs.unitSystem.value,
      distanceUnit:refs.distanceUnit.value,
      temperatureUnit:refs.temperatureUnit.value
    };

    const privacy={
      locationPermission:refs.locationPermission.checked,
      healthDataPermission:refs.healthPermission.checked,
      analyticsConsent:refs.analyticsConsent.checked
    };

    localStorage.setItem(localizationKey,JSON.stringify(localization));
    localStorage.setItem(privacyKey,JSON.stringify(privacy));

    const autosave=JSON.parse(localStorage.getItem('touraysAutosaveSettings')||'{}');
    localStorage.setItem('touraysAutosaveSettings',JSON.stringify({
      ...autosave,
      language:localization.language,
      unitSystem:localization.unitSystem,
      distanceUnit:localization.distanceUnit,
      temperatureUnit:localization.temperatureUnit,
      locationPermission:privacy.locationPermission,
      healthDataPermission:privacy.healthDataPermission,
      analyticsConsent:privacy.analyticsConsent
    }));
  }

  function restoreSettings(){
    const localization=JSON.parse(localStorage.getItem(localizationKey)||'{}');
    const privacy=JSON.parse(localStorage.getItem(privacyKey)||'{}');

    refs.language.value=localization.language||'en';
    refs.unitSystem.value=localization.unitSystem||'metric';
    refs.distanceUnit.value=localization.distanceUnit||'km';
    refs.temperatureUnit.value=localization.temperatureUnit||'c';

    refs.locationPermission.checked=privacy.locationPermission!==false;
    refs.healthPermission.checked=privacy.healthDataPermission!==false;
    refs.analyticsConsent.checked=Boolean(privacy.analyticsConsent);

    refs.offlineSupport.textContent=('serviceWorker' in navigator)?'Available':'Not supported';
    updateUnitSummary();

    const count=localKeys().length;
    refs.dataStatus.textContent='Your data is stored locally on this device.';
    refs.dataDetails.textContent=`${count} Tourays Fitness data group${count===1?' is':'s are'} currently stored.`;
  }

  refs.exportBtn.addEventListener('click',exportData);
  refs.importInput.addEventListener('change',event=>importData(event.target.files?.[0]));
  refs.clearHistoryBtn.addEventListener('click',clearWorkoutHistory);
  refs.resetBtn.addEventListener('click',resetApp);

  refs.unitSystem.addEventListener('change',updateUnitSummary);
  refs.distanceUnit.addEventListener('change',updateUnitSummary);
  refs.temperatureUnit.addEventListener('change',updateUnitSummary);

  refs.form.addEventListener('submit',saveSettings);

  const observer=new MutationObserver(()=>{
    if(!screen.hidden) restoreSettings();
  });
  observer.observe(screen,{attributes:true,attributeFilter:['hidden']});

  restoreSettings();
})();


/* =========================================================
   TOURAYS FITNESS V9 — PROFILE STEP 6: FINAL INTEGRATION & POLISH
   ========================================================= */
(function(){
  const screen=document.getElementById('profileSettingsScreen');
  if(!screen || !document.getElementById('profileCompletionRing')) return;

  const $=id=>document.getElementById(id);
  const refs={
    form:$('profileSettingsForm'),
    completionRing:$('profileCompletionRing'),
    completionValue:$('profileCompletionValue'),
    completionTitle:$('profileCompletionTitle'),
    completionText:$('profileCompletionText'),
    fullName:$('profileFullName'),
    birthDate:$('profileBirthDate'),
    gender:$('profileGender'),
    height:$('profileHeight'),
    weight:$('profileWeight'),
    goalWeight:$('profileGoalWeight'),
    fitnessLevel:$('profileFitnessLevel'),
    weeklyTarget:$('profileWeeklyTarget'),
    duration:$('profileWorkoutDuration'),
    location:$('profileTrainingLocation'),
    calories:$('profileNutritionCalories'),
    protein:$('profileNutritionProtein'),
    water:$('profileNutritionWater'),
    language:$('profileLanguage'),
    unitSystem:$('profileUnitSystem'),
    saveStatus:$('profileSaveStatus')
  };

  function profileCompletion(){
    const checks=[
      Boolean(refs.fullName?.value.trim()),
      Boolean(refs.birthDate?.value),
      Boolean(refs.gender?.value),
      Number(refs.height?.value)>0,
      Number(refs.weight?.value)>0,
      Number(refs.goalWeight?.value)>0,
      Boolean(refs.fitnessLevel?.value),
      Number(refs.weeklyTarget?.value)>0,
      Number(refs.duration?.value)>0,
      Boolean(refs.location?.value),
      Number(refs.calories?.value)>0,
      Number(refs.protein?.value)>0,
      Number(refs.water?.value)>0,
      Boolean(refs.language?.value),
      Boolean(refs.unitSystem?.value)
    ];
    return Math.round((checks.filter(Boolean).length/checks.length)*100);
  }

  function updateCompletion(){
    const value=profileCompletion();
    refs.completionRing.style.setProperty('--profile-progress',value);
    refs.completionValue.textContent=`${value}%`;

    if(value>=100){
      refs.completionTitle.textContent='Your profile is complete';
      refs.completionText.textContent='Coach, planner, nutrition and analytics can now use your full settings.';
    }else if(value>=75){
      refs.completionTitle.textContent='Your setup is almost complete';
      refs.completionText.textContent='Only a few details are missing from your personalized fitness profile.';
    }else if(value>=40){
      refs.completionTitle.textContent='Good progress';
      refs.completionText.textContent='Add the remaining profile and goal information for better recommendations.';
    }else{
      refs.completionTitle.textContent='Complete your fitness profile';
      refs.completionText.textContent='Start with your body metrics, main goal and preferred training setup.';
    }
  }

  function applySharedProfile(){
    const profile=JSON.parse(localStorage.getItem('touraysProfileSettingsV1')||'{}');
    const training=JSON.parse(localStorage.getItem('touraysTrainingPreferencesV1')||'{}');
    const nutrition=JSON.parse(localStorage.getItem('touraysNutritionSettingsV1')||'{}');
    const appPreferences=JSON.parse(localStorage.getItem('touraysAppPreferencesV1')||'{}');
    const localization=JSON.parse(localStorage.getItem('touraysLocalizationSettingsV1')||'{}');

    const shared={
      profile:{
        name:profile.fullName||'',
        birthDate:profile.birthDate||'',
        gender:profile.gender||'',
        fitnessLevel:profile.fitnessLevel||'beginner',
        height:profile.height||null,
        weight:profile.weight||null,
        goalWeight:profile.goalWeight||null,
        goal:profile.goal||'general',
        activityLevel:profile.activityLevel||1.55
      },
      training:{
        duration:training.duration||30,
        workoutTime:training.workoutTime||'evening',
        location:training.location||'mixed',
        weeklyTarget:training.weeklyTarget||3,
        days:training.days||[],
        equipment:training.equipment||[]
      },
      nutrition:{
        mode:nutrition.mode||'auto',
        calories:nutrition.calories||2200,
        protein:nutrition.protein||150,
        carbs:nutrition.carbs||240,
        fat:nutrition.fat||70,
        water:nutrition.water||2500
      },
      preferences:appPreferences,
      localization
    };

    localStorage.setItem('touraysUnifiedProfileV1',JSON.stringify(shared));
    window.dispatchEvent(new CustomEvent('touraysProfileUpdated',{detail:shared}));
  }

  function setActiveTab(group){
    document.querySelectorAll('.profile-settings-tabs button').forEach(button=>{
      button.classList.toggle('active',button.dataset.profileSection===group);
    });
  }

  document.querySelectorAll('.profile-settings-tabs button').forEach(button=>{
    button.addEventListener('click',()=>{
      const group=button.dataset.profileSection;
      const target=screen.querySelector(`[data-profile-group="${group}"]`);
      if(target){
        setActiveTab(group);
        target.scrollIntoView({behavior:'smooth',block:'start'});
      }
    });
  });

  const tracked=[
    ...screen.querySelectorAll('input,select')
  ];
  tracked.forEach(element=>{
    element.addEventListener('input',updateCompletion);
    element.addEventListener('change',updateCompletion);
  });

  refs.form.addEventListener('submit',()=>{
    applySharedProfile();
    updateCompletion();
    refs.saveStatus.textContent='Profile and settings saved across Tourays Fitness.';
    setTimeout(()=>{
      refs.saveStatus.textContent='Changes are saved locally on this device.';
    },1800);
  });

  const groupObserver=new IntersectionObserver(entries=>{
    const visible=entries
      .filter(entry=>entry.isIntersecting)
      .sort((a,b)=>b.intersectionRatio-a.intersectionRatio)[0];
    if(visible?.target?.dataset?.profileGroup){
      setActiveTab(visible.target.dataset.profileGroup);
    }
  },{root:null,threshold:[.2,.45,.7]});

  screen.querySelectorAll('[data-profile-group]').forEach(section=>groupObserver.observe(section));

  const observer=new MutationObserver(()=>{
    if(!screen.hidden){
      updateCompletion();
      applySharedProfile();
    }
  });
  observer.observe(screen,{attributes:true,attributeFilter:['hidden']});

  updateCompletion();
  setActiveTab('personal');
})();


